    ItemCard(english: "Okay, let's go see a movie.", arabic: "تمام، يلا نروح نشوف فيلم."),
    ItemCard(english: "Until then.", arabic: "حتى حينها."),
    ItemCard(english: "Talk to you later.", arabic: "أتكلم معك بعدين."),

    // ===================== إضافات - جمل مع Phone =====================
    ItemCard(english: "Can you answer the phone?", arabic: "ممكن ترد على التليفون؟"),
    ItemCard(english: "I'll call you back later.", arabic: "هتصل بيك تاني بعدين."),
    ItemCard(english: "Please hold on a moment.", arabic: "من فضلك استنى لحظة."),
    ItemCard(english: "She hung up the phone.", arabic: "هي قفلت الخط."),
    ItemCard(english: "My phone is ringing.", arabic: "تليفوني بيرن."),
    ItemCard(english: "He didn't pick up the phone.", arabic: "هو ما ردش على التليفون."),

    // ===================== إضافات - جمل مع May I =====================
    ItemCard(english: "May I come in?", arabic: "هل يمكنني الدخول؟"),
    ItemCard(english: "May I ask you a question?", arabic: "هل يمكنني أسألك سؤال؟"),
    ItemCard(english: "May I use your phone?", arabic: "هل يمكنني أستخدم تليفونك؟"),
    ItemCard(english: "May I help you?", arabic: "هل يمكنني مساعدتك؟"),

    // ===================== إضافات - جمل مع Hang out =====================
    ItemCard(english: "Do you want to hang out tomorrow?", arabic: "عايز نخرج نتمشى بكرة؟"),
    ItemCard(english: "We hang out every weekend.", arabic: "بنخرج كل عطلة نهاية أسبوع."),
    ItemCard(english: "Let's hang out at the mall.", arabic: "يلا نخرج في المول."),

    // ===================== إضافات - جمل مع Have in mind =====================
    ItemCard(english: "What do you have in mind?", arabic: "إيه اللي في بالك؟"),
    ItemCard(english: "I have something in mind.", arabic: "عندي حاجة في بالي."),
    ItemCard(english: "Do you have any plans in mind?", arabic: "عندك أي خطط في بالك؟"),

    // ===================== إضافات - جمل مع Think about / Think of =====================
    ItemCard(english: "I'm thinking about you.", arabic: "أنا بفكر فيك."),
    ItemCard(english: "I can't think of his name.", arabic: "مش قادر أفتكر اسمه."),
    ItemCard(english: "Think about it before you decide.", arabic: "فكر في الموضوع قبل ما تقرر."),
    ItemCard(english: "I just thought of a great idea.", arabic: "لسه خطرت على بالي فكرة عظيمة."),

    // ===================== إضافات - جمل مع My bad =====================
    ItemCard(english: "My bad, I forgot.", arabic: "خطأي، أنا نسيت."),
    ItemCard(english: "My bad, I'm late.", arabic: "خطأي، أنا اتأخرت."),
    ItemCard(english: "My bad, that was my fault.", arabic: "خطأي، ده كان غلطي."),

    // ===================== إضافات - جمل مع Chores =====================
    ItemCard(english: "I have chores to do today.", arabic: "عندي أعمال منزلية أعملها النهاردة."),
    ItemCard(english: "She does the chores every morning.", arabic: "هي بتعمل الأعمال المنزلية كل صباح."),
    ItemCard(english: "We share the chores at home.", arabic: "إحنا بنتقاسم الأعمال المنزلية في البيت."),

    // ===================== إضافات - جمل متنوعة =====================
    ItemCard(english: "Why didn't you answer my call?", arabic: "ليه ما رديتش على مكالمتي؟"),
    ItemCard(english: "I was busy cleaning up.", arabic: "كنت مشغول برتب."),
    ItemCard(english: "What was the reason for your call?", arabic: "إيه كان سبب مكالمتك؟"),
    ItemCard(english: "I want to do something fun tomorrow.", arabic: "عايز أعمل حاجة ممتعة بكرة."),
    ItemCard(english: "Sounds good, let's do it.", arabic: "يبدو جيداً، يلا نعملها."),
    ItemCard(english: "I was thinking about going out.", arabic: "كنت بفكر في الخروج."),
    ItemCard(english: "Let's go see a movie tonight.", arabic: "يلا نروح نشوف فيلم الليلة."),
    ItemCard(english: "Until then, take care.", arabic: "حتى حينها، خد بالك من نفسك."),
    ItemCard(english: "Talk to you later, bye.", arabic: "أتكلم معك بعدين، وداعاً."),
    ItemCard(english: "I've been working here for four years.", arabic: "أنا بعمل هنا لمدة أربع سنوات."),
    ItemCard(english: "I've been watching TV for three hours.", arabic: "أنا بشاهد التلفاز لمدة تلات ساعات."),
    ItemCard(english: "She's been waiting all day.", arabic: "هي بتستنى طوال اليوم."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Conversation Ep2 - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


