class ConversationEp3CompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===================== جمل من الشرح =====================
    ItemCard(english: "I'm in the office.", arabic: "أنا بداخل المكتب."),
