    ItemCard(english: "My stomach is upset. = I have an upset stomach.", arabic: "معدتي مضطربة. = عندي اضطراب في المعدة."),
    ItemCard(english: "My stomach was upset. = I had an upset stomach.", arabic: "كانت معدتي مضطربة. = كان عندي اضطراب في المعدة."),

    // ===================== جمل من المحادثة (Part 1) =====================
