    ItemCard(english: "I wasn't really feeling well.", arabic: "مكنتش حاسس إني كويس بجد."),
    ItemCard(english: "What was wrong with you?", arabic: "إيه كان اللي تعبانك؟"),
    ItemCard(english: "My stomach was upset.", arabic: "معدتي كانت مضطربة."),
