    ItemCard(english: "Would you like anything for your stomach?", arabic: "تحب حاجة لمعدتك؟"),
    ItemCard(english: "I took some medicine earlier.", arabic: "أخدت دواء في وقت سابق."),
    ItemCard(english: "Get better.", arabic: "اتحسن / اشفى."),
