class ConversationEp6CompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===================== جمل من الشرح =====================
    ItemCard(english: "Help someone do something = Help someone to do something.", arabic: "ساعد شخصاً يفعل شيئاً = ساعد شخصاً على فعل شيء."),
    ItemCard(english: "Could you help me find a place = Could you help me to find a place.", arabic: "ممكن تساعدني ألاقي مكان = ممكن تساعدني عشان ألاقي مكان."),
    ItemCard(english: "It's right past that last building on the left.", arabic: "إنه بعد آخر مبنى على اليسار."),
    ItemCard(english: "This is the company where I work.", arabic: "دي الشركة اللي بشتغل فيها."),
