    ItemCard(english: "The weather shifted suddenly.", arabic: "الجو اتغير فجأة."),
    ItemCard(english: "That's a big change.", arabic: "ده تغيير كبير."),
    ItemCard(english: "Can we shift the meeting to tomorrow?", arabic: "ممكن نأجل الاجتماع لبكرة؟"),

    // ===================== إضافات - جمل مع Make it =====================
    ItemCard(english: "I'm sorry, I can't make it to the party.", arabic: "آسف، لا أستطيع الحضور للحفلة."),
    ItemCard(english: "Did you make it to the airport on time?", arabic: "هل استطعت الوصول للمطار في الوقت المحدد؟"),
    ItemCard(english: "You can make it, don't give up!", arabic: "تستطيع تجاوز الأمر، لا تستسلم!"),
    ItemCard(english: "I believe you can make it through this.", arabic: "أنا مؤمن أنك تستطيع تجاوز هذا."),
    ItemCard(english: "She made it to the final round.", arabic: "هي وصلت للدور النهائي."),

    // ===================== إضافات - جمل مع Should have =====================
    ItemCard(english: "You should have told me earlier.", arabic: "كان يجب عليك تقول لي بدري."),
    ItemCard(english: "I should have studied more.", arabic: "كان يجب عليّ أذاكر أكثر."),
    ItemCard(english: "We should have left earlier.", arabic: "كان يجب علينا نمشي بدري."),
    ItemCard(english: "He should have apologized.", arabic: "كان يجب عليه يعتذر."),

    // ===================== إضافات - جمل مع Bother =====================
    ItemCard(english: "Don't bother him, he's working.", arabic: "متزعجوش، هو بيشتغل."),
    ItemCard(english: "I didn't bother to ask.", arabic: "لم أكلف نفسي بالسؤال."),
    ItemCard(english: "Why bother?", arabic: "لماذا نتعب نفسنا؟"),
    ItemCard(english: "She didn't even bother to say goodbye.", arabic: "هي لم تكلف نفسها حتى تقول وداعاً."),

    // ===================== إضافات - جمل مع Feel like =====================
    ItemCard(english: "I feel like eating pizza tonight.", arabic: "أنا أرغب آكل بيتزا الليلة."),
    ItemCard(english: "Do you feel like going out?", arabic: "تحب تخرج؟"),
    ItemCard(english: "I don't feel like talking right now.", arabic: "لا أرغب في الكلام دلوقتي."),
    ItemCard(english: "She feels like watching a movie.", arabic: "هي ترغب تشاهد فيلم."),

    // ===================== إضافات - جمل مع Movies =====================
    ItemCard(english: "Let's go to the movies tonight.", arabic: "يلا نروح السينما الليلة."),
    ItemCard(english: "I watched a great movie yesterday.", arabic: "شاهدت فيلم عظيم امبارح."),
    ItemCard(english: "Have you seen any good films lately?", arabic: "هل شاهدت أي أفلام كويسة مؤخراً؟"),
    ItemCard(english: "The cinema is closed today.", arabic: "السينما مقفولة النهاردة."),
    ItemCard(english: "We can catch a movie this weekend.", arabic: "ممكن نشاهد فيلم عطلة الأسبوع دي."),

    // ===================== إضافات - جمل مع Change of subject =====================
    ItemCard(english: "That's a sudden change of subject.", arabic: "ده تغيير مفاجئ للموضوع."),
    ItemCard(english: "Let's change the subject.", arabic: "يلا نغير الموضوع."),
    ItemCard(english: "Why did you change the subject?", arabic: "لماذا غيرت الموضوع؟"),
    ItemCard(english: "That was a random topic.", arabic: "ده كان موضوع عشوائي."),

    // ===================== إضافات - جمل مع By myself =====================
    ItemCard(english: "I went to the party by myself.", arabic: "ذهبت للحفلة بمفردي."),
    ItemCard(english: "She doesn't like to eat alone.", arabic: "هي لا تحب تاكل بمفردها."),
    ItemCard(english: "Can you do it by yourself?", arabic: "ممكن تعملها بنفسك؟"),
    ItemCard(english: "He traveled by himself.", arabic: "هو سافر بمفرده."),

    // ===================== إضافات - جمل متنوعة =====================
    ItemCard(english: "What's stopping you from traveling?", arabic: "ما الذي يمنعك من السفر؟"),
    ItemCard(english: "Why don't you just ask her?", arabic: "لما لا تسألها فقط؟"),
    ItemCard(english: "I might just stay home tonight.", arabic: "يمكن أفضّل أقعد في البيت الليلة."),
    ItemCard(english: "Are you planning to come?", arabic: "تخطط تجي؟"),
    ItemCard(english: "I haven't seen him lately.", arabic: "لم أره مؤخراً."),
    ItemCard(english: "Have you been to the new restaurant?", arabic: "هل ذهبت للمطعم الجديد؟"),
    ItemCard(english: "That's an odd question.", arabic: "ده سؤال غريب."),
    ItemCard(english: "Just answer the question, please.", arabic: "أجب على السؤال فقط، لو سمحت."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Conversation Ep7 - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


