class ConversationEp9CompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===================== جمل من الشرح =====================
    ItemCard(english: "Invitation = Invitation card.", arabic: "دعوة = كارت دعوة."),
    ItemCard(english: "I guess my invitation got lost in the mail.", arabic: "أظن أن دعوتي قد ضاعت في البريد."),
    ItemCard(english: "May I see your invitation, please?", arabic: "هل تسمح أن أرى كارت الدعوة الخاص بك؟ من فضلك؟"),
    ItemCard(english: "Is that right? = Is that a fact?", arabic: "هل هذا حقيقي؟ = هل هذه حقيقة؟"),
    ItemCard(english: "John broke up with Mary. Is that right?", arabic: "جون انفصل عن ماري. هل هذا حقيقي؟"),
    ItemCard(english: "Did you know that Michael Jackson stole my song?", arabic: "هل تعلم أن مايكل جاكسون قد سرق أغنيتي؟"),
    ItemCard(english: "Wow, is that right? Bad bad Michael!", arabic: "واو، حقاً؟ سيء سيء يا مايكل!"),

    // ===================== جمل من Part 1 =====================
    ItemCard(english: "Has anyone told you about Jessica's party coming up?", arabic: "هل أخبرك أحد عن حفلة جيسيكا القادمة؟"),
    ItemCard(english: "I was told about it already. I'm just waiting for my invitation.", arabic: "لقد أُخبرت عنه بالفعل. أنا فقط أنتظر دعوتي."),
    ItemCard(english: "Is that right? I already got my invitation from her earlier.", arabic: "هل هذا حقيقي؟ أنا بالفعل حصلت على دعوتي منها في وقت سابق."),
    ItemCard(english: "I believe that she will give me the invitation today.", arabic: "أعتقد أنها ستعطيني الدعوة اليوم."),
    ItemCard(english: "Are you even going to go?", arabic: "هل حتى ستذهب؟"),
    ItemCard(english: "Yeah, it sounds like it's going to be the best party of the year.", arabic: "أجل، يبدو أنها ستكون أفضل حفلة في السنة."),

    // ===================== جمل من Part 1 - Loads of =====================
    ItemCard(english: "Exactly, it seems like it's going to be loads of fun.", arabic: "بالضبط، يبدو أنها ستكون الكثير من المرح."),
    ItemCard(english: "When exactly does the party start?", arabic: "متى بالضبط تبدأ الحفلة؟"),
    ItemCard(english: "The invitation says it starts at 08:00 p.m.", arabic: "الدعوة تقول إنها تبدأ الساعة 8 مساءً."),
    ItemCard(english: "Has she given out a lot of invitations yet?", arabic: "هل وزعت الكثير من الدعوات بعد؟"),
    ItemCard(english: "I have no idea she hasn't given out many though.", arabic: "ليس لدي فكرة، لكنها لم توزع الكثير."),
    ItemCard(english: "I'm planning on going, but I really need her to give me my invitation.", arabic: "أنا أخطط للذهاب، لكني حقاً أحتاجها أن تعطيني دعوتي."),

    // ===================== جمل من Part 2 =====================
    ItemCard(english: "Have you heard about Jessica's party on Saturday?", arabic: "هل سمعت عن حفلة جيسيكا يوم السبت؟"),
    ItemCard(english: "I've heard about it, but I'm still waiting for my invitation.", arabic: "سمعت عنها، لكني ما زلت أنتظر دعوتي."),
    ItemCard(english: "Really? I got mine from her this morning.", arabic: "حقاً؟ أنا حصلت على دعوتي منها هذا الصباح."),
    ItemCard(english: "I'm guessing that she's going to give me my invitation today or tomorrow.", arabic: "أخمن أنها ستعطيني دعوتي اليوم أو غداً."),
    ItemCard(english: "You're probably right, do you intend on going to the party?", arabic: "أنت على الأرجح محق، هل تنوي الذهاب للحفلة؟"),
    ItemCard(english: "I want to. I heard it's going to be really fun.", arabic: "أريد ذلك. سمعت أنها ستكون ممتعة حقاً."),

    // ===================== جمل من Part 2 - Supposed to & Give out =====================
    ItemCard(english: "It's supposed to start at about eight.", arabic: "من المفترض أن تبدأ حوالي الثامنة."),
    ItemCard(english: "I know, It does sound pretty awesome.", arabic: "أعرف، يبدو رائعاً جداً."),
    ItemCard(english: "Well, when does the party start?", arabic: "حسناً، متى تبدأ الحفلة؟"),
    ItemCard(english: "How many invitations has she given out?", arabic: "كم دعوة وزعت؟"),
    ItemCard(english: "I don't know, but I don't think she gave out that many yet.", arabic: "لا أعرف، لكني لا أعتقد أنها وزعت الكثير بعد."),
    ItemCard(english: "I really want to go, so I hope that she gives me my invitation soon.", arabic: "أنا حقاً أريد الذهاب، لذا آمل أنها تعطيني دعوتي قريباً."),
    ItemCard(english: "I gave out samples and everyone said it was the bomb.", arabic: "وزعت عينات وكل الناس قالوا إنها الأفضل."),
    ItemCard(english: "My computer just gave out, I think I'll have to buy a new one.", arabic: "الكمبيوتر توقف عن العمل، أظن أني سأضطر لشراء جهاز جديد."),
    ItemCard(english: "People's hearts give out all the time, man.", arabic: "يحدث كثيراً أن تتوقف قلوب الناس عن العمل، يا راجل."),

    // ===================== جمل من Part 3 =====================
    ItemCard(english: "Later = Later on.", arabic: "لاحقاً = لاحقاً."),
    ItemCard(english: "I am planning a trip to Europe.", arabic: "أنا أخطط رحلة لأوروبا."),
    ItemCard(english: "I am planning to go to Europe.", arabic: "أنا أخطط أن أذهب لأوروبا."),
    ItemCard(english: "I am planning on going to Europe.", arabic: "أنا أخطط للذهاب إلى أوروبا."),
    ItemCard(english: "I intend to go Europe.", arabic: "أنوي أن أذهب لأوروبا."),
    ItemCard(english: "I intend on going to Europe.", arabic: "أنوي الذهاب إلى أوروبا."),
    ItemCard(english: "Hey, did you hear about Jessica's party this weekend?", arabic: "هاي، هل سمعت عن حفلة جيسيكا عطلة الأسبوع دي؟"),
    ItemCard(english: "Yeah, but I'm still waiting for my invitation.", arabic: "أجل، لكني ما زلت أنتظر دعوتي."),
    ItemCard(english: "Oh really? She gave me mine earlier today.", arabic: "أوه حقاً؟ هي أعطتني دعوتي في وقت سابق اليوم."),
    ItemCard(english: "Well, she'll probably just give me my invitation later on today.", arabic: "حسناً، على الأرجح ستعطيني دعوتي لاحقاً اليوم."),
    ItemCard(english: "Yeah, so are you planning on going?", arabic: "أجل، هل تخطط للذهاب؟"),
    ItemCard(english: "I think so. It sounds like it's going to be a lot of fun.", arabic: "أعتقد ذلك. يبدو أنها ستكون الكثير من المرح."),

    // ===================== جمل من Part 3 - It really does & Come up =====================
    ItemCard(english: "It really does. I can't wait.", arabic: "إنها حقاً كذلك. لا أستطيع الانتظار."),
    ItemCard(english: "It really does = It really does sound like.", arabic: "إنها حقاً كذلك = إنها حقاً تبدو كذلك."),
    ItemCard(english: "You know what holiday is coming up, don't you?", arabic: "أنت تعرف أي إجازة على وشك أن تأتي، أليس كذلك؟"),
    ItemCard(english: "What time does the party start?", arabic: "في أي وقت تبدأ الحفلة؟"),
    ItemCard(english: "Oh, well, how many people has she given invitation to so far?", arabic: "أوه، حسناً، كم شخصاً أعطته دعوة حتى الآن؟"),
    ItemCard(english: "Mark come up to me and whispered in my ear.", arabic: "مارك اقترب مني وهمس في أذني."),
    ItemCard(english: "On the subway, a man come up to me to start a conversation.", arabic: "في المترو، اقترب مني رجل ليبدأ محادثة."),
    ItemCard(english: "I can come up with good excuse.", arabic: "يمكنني أن آتي بعذر جيد."),
    ItemCard(english: "I'm not sure, but I don't think she's given out that many.", arabic: "لست متأكداً، لكني لا أعتقد أنها وزعت الكثير."),
    ItemCard(english: "Well, hopefully she'll give me my invitation later on today.", arabic: "حسناً، على أمل أنها ستعطيني دعوتي لاحقاً اليوم."),

    // ===================== إضافات - جمل مع Invitation =====================
    ItemCard(english: "Did you get your invitation to the wedding?", arabic: "هل حصلت على دعوتك للفرح؟"),
    ItemCard(english: "I sent out all the invitations yesterday.", arabic: "أرسلت كل الدعوات امبارح."),
    ItemCard(english: "The invitation says to dress formally.", arabic: "الدعوة بتقول إننا نلبس رسمي."),
    ItemCard(english: "She forgot to send me an invitation.", arabic: "هي نسيت تبعتلي دعوة."),
    ItemCard(english: "Thank you for the invitation.", arabic: "شكراً على الدعوة."),

    // ===================== إضافات - جمل مع Is that right? =====================
    ItemCard(english: "Is that right? I didn't know that.", arabic: "هل هذا حقيقي؟ لم أكن أعرف ذلك."),
    ItemCard(english: "Is that right? Tell me more.", arabic: "هل هذا حقيقي؟ قول لي المزيد."),
    ItemCard(english: "Wow, is that right? That's amazing!", arabic: "واو، حقاً؟ ده مذهل!"),
    ItemCard(english: "Is that a fact? I find that hard to believe.", arabic: "هل هذه حقيقة؟ أجد صعوبة في تصديق ذلك."),

    // ===================== إضافات - جمل مع Loads of =====================
    ItemCard(english: "There were loads of people at the party.", arabic: "كان في الكثير من الناس في الحفلة."),
    ItemCard(english: "She has loads of friends.", arabic: "عندها الكثير من الأصدقاء."),
    ItemCard(english: "We had loads of fun last night.", arabic: "اتمتعنا بالكثير من المرح امبارح بالليل."),
    ItemCard(english: "Loads of = Much = Many.", arabic: "الكثير من = كثير = كثير."),

    // ===================== إضافات - جمل مع Give out =====================
    ItemCard(english: "Can you give out these papers to the students?", arabic: "ممكن توزع الأوراق دي على الطلاب؟"),
    ItemCard(english: "The teacher gave out the exam results.", arabic: "المدرس وزع نتائج الامتحان."),
    ItemCard(english: "My phone gave out after 3 years.", arabic: "تليفوني توقف عن العمل بعد 3 سنين."),
    ItemCard(english: "Give out = Distribute / Stop working.", arabic: "يوزع = يوزع / يتوقف عن العمل."),

    // ===================== إضافات - جمل مع Plan to / Plan on =====================
    ItemCard(english: "I'm planning to visit my parents next week.", arabic: "أنا أخطط لزيارة والدي الأسبوع الجاي."),
    ItemCard(english: "She's planning on studying abroad.", arabic: "هي تخطط للدراسة في الخارج."),
    ItemCard(english: "We plan to leave early tomorrow.", arabic: "نخطط نمشي بدري بكرة."),
    ItemCard(english: "He plans on buying a new car.", arabic: "هو يخطط يشتري عربية جديدة."),

    // ===================== إضافات - جمل مع Intend to / Intend on =====================
    ItemCard(english: "I intend to finish this project today.", arabic: "أنوي إنهاء المشروع ده النهاردة."),
    ItemCard(english: "She intends on traveling next month.", arabic: "هي تنوي السفر الشهر الجاي."),
    ItemCard(english: "Do you intend to come to the meeting?", arabic: "تنوي تحضر الاجتماع؟"),
    ItemCard(english: "We intend on staying for a week.", arabic: "ننوي نبقى لمدة أسبوع."),

    // ===================== إضافات - جمل مع Come up =====================
    ItemCard(english: "My birthday is coming up next week.", arabic: "عيد ميلادي قادم الأسبوع الجاي."),
    ItemCard(english: "Something important came up, I have to leave.", arabic: "حصل شيء مهم، لازم أمشي."),
    ItemCard(english: "She came up to me and said hello.", arabic: "هي اقتربت مني وقالت أهلاً."),
    ItemCard(english: "I can't come up with a good idea.", arabic: "مش قادر آتي بفكرة كويسة."),

    // ===================== إضافات - جمل مع Supposed to =====================
    ItemCard(english: "I'm supposed to be at work at 9 AM.", arabic: "من المفترض أكون في الشغل الساعة 9 الصبح."),
    ItemCard(english: "You're not supposed to smoke here.", arabic: "مش المفروض تدخن هنا."),
    ItemCard(english: "The party is supposed to start at 8 PM.", arabic: "الحفلة من المفترض تبدأ الساعة 8 مساءً."),
    ItemCard(english: "She was supposed to call me yesterday.", arabic: "كان المفروض تتصل بي امبارح."),

    // ===================== إضافات - جمل متنوعة =====================
    ItemCard(english: "I heard about the party, but I didn't get an invitation.", arabic: "سمعت عن الحفلة، بس مجتليش دعوة."),
    ItemCard(english: "Are you going to attend the party?", arabic: "هتحضر الحفلة؟"),
    ItemCard(english: "I really hope she gives me my invitation soon.", arabic: "أنا حقاً آمل إنها تعطيني دعوتي قريباً."),
    ItemCard(english: "It sounds like it's going to be a lot of fun.", arabic: "يبدو إنها هتكون ممتعة جداً."),
    ItemCard(english: "I can't wait for the party!", arabic: "مش قادر أستنى الحفلة!"),
    ItemCard(english: "When does the party start?", arabic: "الحفلة بتبدأ إمتى؟"),
    ItemCard(english: "How many people are coming?", arabic: "كام شخص هيجي؟"),
    ItemCard(english: "Is it going to be a big party?", arabic: "هتكون حفلة كبيرة؟"),
    ItemCard(english: "I'm really looking forward to it.", arabic: "أنا حقاً متطلع ليها."),
    ItemCard(english: "Sounds like a great plan.", arabic: "تبدو خطة عظيمة."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Conversation Ep9 - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


