class ConversationEp10CompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===================== جمل من الشرح =====================
    ItemCard(english: "What do you think you're doing?", arabic: "ماذا تظن نفسك فاعلاً؟"),
    ItemCard(english: "\"What do you think you're doing?\" Is not a real question. It's just a way to show that you're surprised or displeased with someone's action.", arabic: "\"ماذا تظن نفسك فاعلاً؟\" ليس سؤالاً حقيقياً. إنه مجرد طريقة لإظهار أنك متفاجئ أو غير راضٍ عن تصرف شخص ما."),
    ItemCard(english: "When people are angry, they usually say \"What the heck do you think you're doing?\"", arabic: "عندما يغضب الناس، عادةً يقولون \"ماذا بحق الجحيم تظن نفسك فاعلاً؟\""),
    ItemCard(english: "The word heck, is the polite way of saying \"hell\". Don't say hell, it's not polite.", arabic: "كلمة heck هي الطريقة المهذبة لقول \"hell\". لا تقل hell، فهي غير مهذبة."),
    ItemCard(english: "I can't study at home, because my family talks so loudly.", arabic: "لا أستطيع الدراسة في المنزل، لأن أفراد عائلتي يتحدثون بصوت عالٍ."),
    ItemCard(english: "The word \"family\" is a collective noun.", arabic: "كلمة \"family\" هي اسم جماعي."),
    ItemCard(english: "Collective nouns are names of collections of people or things.", arabic: "الأسماء الجماعية هي أسماء مجموعات من الناس أو الأشياء."),
    ItemCard(english: "Team = a collection of players.", arabic: "فريق = مجموعة من اللاعبين."),
    ItemCard(english: "Staff = a collection of people who work in the same place.", arabic: "طاقم العمل = مجموعة من الأشخاص الذين يعملون في نفس المكان."),
    ItemCard(english: "Flock = a collection of birds.", arabic: "سرب = مجموعة من الطيور."),

    // ===================== جمل من الشرح - Collective nouns =====================
    ItemCard(english: "Collective nouns can be thought of as single or plural nouns.", arabic: "يمكن اعتبار الأسماء الجماعية أسماء مفردة أو جمع."),
    ItemCard(english: "Sometimes we can use collective nouns as single. My family talks.", arabic: "أحياناً نستخدم الأسماء الجماعية كمفرد. عائلتي تتحدث."),
    ItemCard(english: "We added (s) because we treated the word \"family\" as a single noun.", arabic: "أضفنا (s) لأننا عاملنا كلمة \"family\" كاسم مفرد."),
    ItemCard(english: "And sometimes we will use it as plural. Saw a flock of sheep.", arabic: "وأحياناً نستخدمها كجمع. رأيت سرباً من الخرفان."),
    ItemCard(english: "The verb that follows will not need an extra (s).", arabic: "الفعل الذي يليها لن يحتاج (s) إضافية."),
    ItemCard(english: "I'll give it a shot. That's an idiom. Meaning: to give something a shot is to try to do it.", arabic: "سأجربها. هذا تعبير اصطلاحي. المعنى: أن تجرب شيئاً هو أن تحاول فعله."),
    ItemCard(english: "Dude is American English slang for \"guy\" or \"man\" or in other countries like Australia or England \"mate\".", arabic: "Dude هي عامية أمريكية تعني \"guy\" أو \"man\" أو في دول أخرى مثل أستراليا أو إنجلترا \"mate\"."),
    ItemCard(english: "They tend to close late. Tend to do something means: to frequently do it. You can think of it as saying \"usually\".", arabic: "هم يميلون إلى الإغلاق متأخراً. Tend to do something تعني: أن تفعلها بشكل متكرر. يمكنك اعتبارها بمعنى \"عادةً\"."),

    // ===================== جمل المحادثة - Part 1 =====================
    ItemCard(english: "Hey, what do you think you're doing?", arabic: "هاي، ماذا تظن نفسك فاعلاً؟"),
    ItemCard(english: "I can't study at home, because my family talks so loudly.", arabic: "لا أستطيع الدراسة في المنزل، لأن أفراد عائلتي يتحدثون بصوت عالٍ."),
    ItemCard(english: "Well, study at the library then.", arabic: "حسناً، ادرس في المكتبة إذن."),
    ItemCard(english: "Can you really focus in there?", arabic: "هل يمكنك حقاً التركيز هناك؟"),
    ItemCard(english: "Yes, it's always really quiet.", arabic: "نعم، إنها حقاً هادئة دائماً."),
    ItemCard(english: "I'll give it a shot today.", arabic: "سوف أقوم بتجربتها اليوم."),
    ItemCard(english: "When you do, make sure you get a good seat.", arabic: "عند القيام بذلك، تأكد من حصولك على مقعد جيد."),

    // ===================== جمل المحادثة - Part 2 =====================
    ItemCard(english: "Why? Are there not enough seats for everyone?", arabic: "لماذا؟ ألا توجد مقاعد كافية للجميع؟"),
    ItemCard(english: "It depends on when you go.", arabic: "ذلك يعتمد على وقت ذهابك."),
    ItemCard(english: "I'm going at 1:00 a.m.", arabic: "سوف أذهب في الواحدة صباحاً."),
    ItemCard(english: "Dude, it's not even open that late.", arabic: "يا صاحبي، لن تكون مفتوحة في ذلك الوقت المتأخر."),
    ItemCard(english: "But that's the best time for me.", arabic: "ولكن هذا هو أفضل وقت بالنسبة لي."),
    ItemCard(english: "You can always try a cafe. They tend to close late or sometimes not at all.", arabic: "يمكنك دائماً تجربة مقهى. ما يفضلون الإغلاق في وقت متأخر أو لا يغلقون على الإطلاق."),
    ItemCard(english: "Alright. Good one.", arabic: "حسناً. فكرة جيدة."),

    // ===================== إضافات - جمل مع What do you think you're doing? =====================
    ItemCard(english: "What do you think you're doing with my phone?", arabic: "ماذا تظن نفسك فاعلاً بتليفوني؟"),
    ItemCard(english: "What the heck do you think you're doing?", arabic: "ماذا بحق الجحيم تظن نفسك فاعلاً؟"),
    ItemCard(english: "What on earth do you think you're doing?", arabic: "ماذا بحق الأرض تظن نفسك فاعلاً؟"),
    ItemCard(english: "Hey! What do you think you're doing here?", arabic: "هاي! ماذا تظن نفسك فاعلاً هنا؟"),

    // ===================== إضافات - جمل مع Collective nouns =====================
    ItemCard(english: "My family talks so loudly.", arabic: "عائلتي تتحدث بصوت عالٍ جداً."),
    ItemCard(english: "My family talk so loudly.", arabic: "أفراد عائلتي يتحدثون بصوت عالٍ جداً."),
    ItemCard(english: "The team is playing well today.", arabic: "الفريق يلعب جيداً اليوم."),
    ItemCard(english: "The team are playing well today.", arabic: "أفراد الفريق يلعبون جيداً اليوم."),
    ItemCard(english: "The staff is very helpful.", arabic: "طاقم العمل مفيد جداً."),
    ItemCard(english: "A flock of birds flew over us.", arabic: "سرب من الطيور طار فوقنا."),
    ItemCard(english: "A flock of sheep is in the field.", arabic: "سرب من الخرفان في الحقل."),

    // ===================== إضافات - جمل مع Give it a shot =====================
    ItemCard(english: "I'll give it a shot today.", arabic: "سأجربها اليوم."),
    ItemCard(english: "Why don't you give it a shot?", arabic: "لما لا تجربها؟"),
    ItemCard(english: "I gave it a shot, but it didn't work.", arabic: "جربتها، لكنها لم تنجح."),
    ItemCard(english: "Give it a shot, you might like it.", arabic: "جربها، ممكن تعجبك."),

    // ===================== إضافات - جمل مع Tend to =====================
    ItemCard(english: "They tend to close late.", arabic: "هم يميلون إلى الإغلاق متأخراً."),
    ItemCard(english: "I tend to wake up early.", arabic: "أنا عادةً أصحى بدري."),
    ItemCard(english: "She tends to forget things.", arabic: "هي عادةً تنسى الأشياء."),
    ItemCard(english: "People tend to be busy on Mondays.", arabic: "الناس عادةً يكونون مشغولين يوم الاتنين."),

    // ===================== إضافات - جمل مع Depends on =====================
    ItemCard(english: "It depends on when you go.", arabic: "ذلك يعتمد على وقت ذهابك."),
    ItemCard(english: "It depends on the weather.", arabic: "ذلك يعتمد على الجو."),
    ItemCard(english: "Everything depends on your decision.", arabic: "كل حاجة بتعتمد على قرارك."),
    ItemCard(english: "I might go, it depends on my schedule.", arabic: "ممكن أروح، ده يعتمد على جدولي."),

    // ===================== إضافات - جمل مع Make sure =====================
    ItemCard(english: "Make sure you get a good seat.", arabic: "تأكد من حصولك على مقعد جيد."),
    ItemCard(english: "Make sure to lock the door.", arabic: "تأكد من قفل الباب."),
    ItemCard(english: "Make sure you're on time.", arabic: "تأكد إنك تكون في الوقت المحدد."),
    ItemCard(english: "I'll make sure everything is ready.", arabic: "هتأكد إن كل حاجة جاهزة."),

    // ===================== إضافات - جمل مع Cafe =====================
    ItemCard(english: "You can always try a cafe.", arabic: "يمكنك دائماً تجربة مقهى."),
    ItemCard(english: "Let's meet at the cafe.", arabic: "يلا نتقابل في المقهى."),
    ItemCard(english: "The cafe is open until midnight.", arabic: "المقهى مفتوح لحد نص الليل."),
    ItemCard(english: "I like studying in a cafe.", arabic: "أنا بحب أدرس في مقهى."),

    // ===================== إضافات - جمل مع Study =====================
    ItemCard(english: "I can't study at home.", arabic: "لا أستطيع الدراسة في المنزل."),
    ItemCard(english: "I need to study for the exam.", arabic: "أحتاج أدرس للامتحان."),
    ItemCard(english: "She studies at the library every day.", arabic: "هي بتدرس في المكتبة كل يوم."),
    ItemCard(english: "Let's study together.", arabic: "يلا ندرس معاً."),

    // ===================== إضافات - جمل مع Focus =====================
    ItemCard(english: "Can you really focus in there?", arabic: "هل يمكنك حقاً التركيز هناك؟"),
    ItemCard(english: "I can't focus with all this noise.", arabic: "مش قادر أركز مع كل الضوضاء دي."),
