    ItemCard(english: "Thanks, dude!", arabic: "شكراً يا صاحبي!"),
    ItemCard(english: "What the heck is going on?", arabic: "إيه اللي بيحصل ده؟"),
    ItemCard(english: "This place tends to be crowded.", arabic: "المكان ده عادةً بيكون زحمة."),
    ItemCard(english: "I'll try the library tomorrow.", arabic: "هجرب المكتبة بكرة."),
    ItemCard(english: "I gave it a shot, and it worked!", arabic: "جربتها، ونجحت!"),
    ItemCard(english: "You should give it a shot.", arabic: "لازم تجربها."),
