class ConversationEp11CompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===================== جمل من الشرح =====================
    ItemCard(english: "\"Can you please shut up?\" The word \"shut up\" isn't usually polite. He was angry. That's why he used the word \"shut up\".", arabic: "\"من فضلك هل يمكنك أن تغلق فمك؟\" كلمة \"shut up\" عادةً ليست مهذبة. كان غاضباً. لهذا استخدم كلمة \"shut up\"."),
    ItemCard(english: "He could have said other things and would have been much nicer.", arabic: "كان يمكنه قول أشياء أخرى وكان سيكون ألطف بكثير."),
    ItemCard(english: "Could you please speak a bit quieter?", arabic: "ممكن تتحدث بصوت أهدأ قليلاً؟"),
    ItemCard(english: "I'm sorry, would you mind keeping it down?", arabic: "أنا آسف، هل تمانع في خفض صوتك؟"),
    ItemCard(english: "\"Maybe if you ask nicely\" It means you admit that what you're doing is not ideal but you aren't happy with the method of bringing your attention to it.", arabic: "\"ربما إذا سألت بلطف\" تعني أنك تعترف أن ما تفعله ليس مثالياً لكنك لست سعيداً بالطريقة التي لُفت بها انتباهك إلى ذلك."),
    ItemCard(english: "It's like saying \"Ok, I know my behavior isn't the best, but I don't appreciate the way you're talking to me\".", arabic: "إنها مثل قول \"حسناً، أنا أعرف أن سلوكي ليس الأفضل، لكني لا أقدّر الطريقة التي تتحدث بها معي\"."),
    ItemCard(english: "\"I have no interest in splitting hairs\" That's an idiom.", arabic: "\"ليس لدي أي رغبة في الدخول بجدال غير مجدي\" هذا تعبير اصطلاحي."),
    ItemCard(english: "If we say that someone is splitting hairs, what we actually mean is they are trying to argue about very small and unimportant details.", arabic: "إذا قلنا أن شخصاً ما يجادل في تفاهات، ما نعنيه فعلاً هو أنه يحاول الجدال حول تفاصيل صغيرة وغير مهمة."),
    ItemCard(english: "A: The president is 64 years old. B: No, you're wrong. He is only 63 and half.", arabic: "أ: الرئيس عمره 64 سنة. ب: لا، أنت مخطئ. عمره 63 سنة ونصف فقط."),
    ItemCard(english: "As you can see, arguing about that is a waste of time. It's splitting hairs.", arabic: "كما ترى، الجدال حول ذلك مضيعة للوقت. إنه جدال في تفاهات."),
    ItemCard(english: "\"I'm sorry that your parents didn't teach you how to be nice\" This is a very annoying statement.", arabic: "\"أنا آسف لأن والديك لم يعلماك كيف تكون لطيفاً\" هذه جملة مزعجة جداً."),
    ItemCard(english: "It's like he's saying. \"Well, it seems you are fixating on me having to say sorry. Ok, I will give you the sorry that you're looking for but you're not gonna like it\".", arabic: "يبدو وكأنه يقول: \"حسناً، يبدو أنك تركز على أنه يجب عليّ أن أقول آسف. حسناً، سأعطيك الاعتذار الذي تبحث عنه لكنك لن تحبه\"."),

    // ===================== جمل المحادثة - Part 1 =====================
    ItemCard(english: "Hhhhhh", arabic: "هههههه"),
    ItemCard(english: "Can you please shut up?", arabic: "من فضلك هل يمكنك أن تغلق فمك؟"),
    ItemCard(english: "This is a library, so you have to shut up.", arabic: "هذه مكتبة، لذا عليك أن تصمت."),
