class ConversationEp13CompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===================== جمل من الشرح =====================
    ItemCard(english: "A: What's up man? B: Nothing much.", arabic: "أ: كيف حالك يا رجل؟ ب: لا جديد."),
    ItemCard(english: "When you say nothing much in response to someone asking how you're doing. It means \"Nothing important\".", arabic: "عندما تقول nothing much رداً على سؤال كيف حالك، فهي تعني \"لا شيء مهم\"."),
    ItemCard(english: "B: How are you doing? A: Better than I deserve.", arabic: "ب: كيف حالك؟ أ: أفضل مما أستحق."),
    ItemCard(english: "When you are happy with how everything is going in your life, you can use that \"Better than I deserve\" or \"Can't complain\".", arabic: "عندما تكون سعيداً بسير كل شيء في حياتك، يمكنك استخدام \"أفضل مما أستحق\" أو \"لا أستطيع الشكوى\"."),
    ItemCard(english: "Can't complain means you're satisfied with how everything is going in your life.", arabic: "Can't complain تعني أنك راضٍ عن سير كل شيء في حياتك."),
    ItemCard(english: "\"To what do I owe the pleasure?\" This is a good way to ask why someone is calling.", arabic: "\"لماذا سررت باتصالك؟\" هذه طريقة جيدة للسؤال عن سبب اتصال شخص ما."),
    ItemCard(english: "To what do I owe the pleasure is used when you want to ask why someone is contacting you.", arabic: "To what do I owe the pleasure تُستخدم عندما تريد السؤال عن سبب تواصل شخص معك."),
    ItemCard(english: "If we say \"Why are you calling me?\" That could be very rude.", arabic: "إذا قلنا \"لماذا تتصل بي؟\" فقد يكون ذلك وقحاً جداً."),
    ItemCard(english: "It's like you're saying \"I don't want to hear from you. Stop calling me\".", arabic: "يبدو وكأنك تقول \"لا أريد أن أسمع منك. توقف عن الاتصال بي\"."),
    ItemCard(english: "\"I was wondering if you could hook me up at the place you work\" Hook me up is a phrasal verb. It has several meanings.", arabic: "\"كنت أتساءل إن كان بإمكانك أن تتوسط لي للحصول على وظيفة في مكان عملك\" Hook me up هو فعل مركب. له عدة معانٍ."),
    ItemCard(english: "In American English when you say hook someone up with something. It means that you will give them something through your connection. Your connection of people, or contacts.", arabic: "في الإنجليزية الأمريكية عندما تقول hook someone up with something، فهي تعني أنك ستعطيهم شيئاً من خلال معارفك. معارفك من الناس أو جهات الاتصال."),
    ItemCard(english: "\"You're the bomb!\" When we say that something or someone is the bomb. That's slang for saying \"you're cool\" - \"You're awesome\" - \"you're great\".", arabic: "\"أنت رائع!\" عندما نقول أن شيئاً أو شخصاً ما هو the bomb. هذه عامية لقول \"أنت رائع\" - \"أنت مذهل\" - \"أنت عظيم\"."),
    ItemCard(english: "\"I'm learning to keep my chin up.\" To keep your chin up is an idiom that means \"that you're trying to remain happy, cheerful and to keep having hope especially in difficult times\".", arabic: "\"أنا أتعلم أن أتفاءل.\" To keep your chin up هو تعبير اصطلاحي يعني \"أنك تحاول أن تبقى سعيداً ومبتهجاً وتحافظ على الأمل خاصة في الأوقات الصعبة\"."),

    // ===================== جمل المحادثة - Part 1 =====================
    ItemCard(english: "Hey Mark. What's up man?", arabic: "مرحباً مارك. كيف حالك يا رجل؟"),
    ItemCard(english: "Hi, Jack. Nothing much. How are you doing?", arabic: "أهلاً جاك. لا جديد. كيف حالك؟"),
    ItemCard(english: "Better than I deserve. To what do I owe the pleasure?", arabic: "أفضل مما أستحق. لماذا سررت باتصالك؟"),
    ItemCard(english: "I'm looking for a job. I was hoping you could help me.", arabic: "أبحث عن وظيفة. كنت أتمنى أن تستطيع مساعدتي."),
    ItemCard(english: "Sure, how can I help?", arabic: "بالتأكيد، كيف يمكنني مساعدتك؟"),
    ItemCard(english: "Well, I was wondering if you could hook me up at the place you work.", arabic: "حسناً، كنت أتساءل إن كان بإمكانك أن تتوسط لي للحصول على وظيفة في مكان عملك."),

    // ===================== جمل المحادثة - Part 2 =====================
    ItemCard(english: "No problem. I don't know if they're hiring, but I'll find out.", arabic: "لا مشكلة. لا أعرف إذا كانوا يوظفون، لكني سأكتشف ذلك."),
    ItemCard(english: "Thanks man, you're the bomb!", arabic: "شكراً يا رجل، أنت رائع!"),
    ItemCard(english: "What kind of job are you interested in doing?", arabic: "أي نوع من الوظائف أنت مهتم بالقيام به؟"),
    ItemCard(english: "Anything you think that I can do will be fine.", arabic: "أي شيء تعتقد أني أستطيع فعله سيكون جيداً."),
    ItemCard(english: "Can't you be a little more specific?", arabic: "هل يمكنك أن تكون أكثر تحديداً؟"),
    ItemCard(english: "I wish I could, man but honestly any thing would be fine.", arabic: "أتمنى لو كنت أستطيع، صدقني يا رجل أي شيء سيكون جيداً بالنسبة لي."),

    // ===================== جمل المحادثة - Part 3 =====================
    ItemCard(english: "That bad, ha?", arabic: "ألهذه الدرجة، ها؟"),
    ItemCard(english: "Well, I'm learning to keep my chin up.", arabic: "حسناً، ما زلت أتمسك بالأمل."),
    ItemCard(english: "Good man. I'll talk to my boss in the morning and get back to you.", arabic: "جيد. سأتحدث إلى رئيسي بالعمل صباحاً ثم سأخبرك."),
    ItemCard(english: "Thanks, man. A friend in need is a friend indeed.", arabic: "شكراً يا رجل. الصديق وقت الضيق."),
    ItemCard(english: "Of course. Anything else you need me to do?", arabic: "بالتأكيد. هل هناك شيء آخر أستطيع مساعدتك به؟"),
    ItemCard(english: "No. I'm waiting to hear from you.", arabic: "لا. أنا في انتظار ردك."),
    ItemCard(english: "Alright, take care.", arabic: "حسناً، اعتن بنفسك."),
    ItemCard(english: "Yeah, you too.", arabic: "أجل، وأنت أيضاً."),

    // ===================== إضافات - جمل مع What's up? =====================
    ItemCard(english: "Hey, what's up?", arabic: "هاي، إيه الأخبار؟"),
    ItemCard(english: "What's up with you these days?", arabic: "إيه أخبارك الأيام دي؟"),
    ItemCard(english: "Nothing much, just working.", arabic: "لا جديد، بس بشتغل."),
    ItemCard(english: "What's up man? Long time no see!", arabic: "إيه الأخبار يا راجل؟ بقالي كتير مشفتكش!"),

    // ===================== إضافات - جمل مع Better than I deserve / Can't complain =====================
    ItemCard(english: "Better than I deserve.", arabic: "أفضل مما أستحق."),
    ItemCard(english: "Can't complain, life is good.", arabic: "مش بشتكي، الحياة حلوة."),
    ItemCard(english: "I'm doing great, can't complain.", arabic: "أنا كويس، مش بشتكي."),
    ItemCard(english: "Better than I deserve, thank God.", arabic: "أفضل مما أستحق، الحمد لله."),

    // ===================== إضافات - جمل مع To what do I owe the pleasure? =====================
    ItemCard(english: "To what do I owe the pleasure?", arabic: "لماذا سررت باتصالك؟"),
    ItemCard(english: "To what do I owe the pleasure of this visit?", arabic: "لماذا سررت بهذه الزيارة؟"),
    ItemCard(english: "To what do I owe the pleasure of your call?", arabic: "لماذا سررت بمكالمتك؟"),
    ItemCard(english: "What brings you here?", arabic: "إيه اللي جابك هنا؟"),

    // ===================== إضافات - جمل مع Hook me up =====================
    ItemCard(english: "Can you hook me up with a job?", arabic: "ممكن تتوسط لي بوظيفة؟"),
    ItemCard(english: "He hooked me up with a great deal.", arabic: "هو وسط لي بصفقة عظيمة."),
    ItemCard(english: "Can you hook me up with tickets?", arabic: "ممكن توصلني بتذاكر؟"),
    ItemCard(english: "She hooked me up with her friend.", arabic: "هي عرفتني على صاحبتها."),

    // ===================== إضافات - جمل مع You're the bomb =====================
    ItemCard(english: "Thanks man, you're the bomb!", arabic: "شكراً يا رجل، أنت رائع!"),
    ItemCard(english: "That party was the bomb!", arabic: "الحفلة دي كانت رائعة!"),
    ItemCard(english: "You're the bomb, thanks for helping!", arabic: "أنت رائع، شكراً على المساعدة!"),
    ItemCard(english: "This food is the bomb!", arabic: "الأكل ده رائع!"),

    // ===================== إضافات - جمل مع Keep my chin up =====================
    ItemCard(english: "I'm learning to keep my chin up.", arabic: "أنا أتعلم أن أتفاءل."),
    ItemCard(english: "Keep your chin up, things will get better.", arabic: "ارفع رأسك، الأمور هتتحسن."),
    ItemCard(english: "She kept her chin up during hard times.", arabic: "هي حافظت على أملها في الأوقات الصعبة."),
    ItemCard(english: "Keep your chin up and don't give up.", arabic: "تفاءل ومتستسلمش."),

    // ===================== إضافات - جمل مع Friend in need =====================
    ItemCard(english: "A friend in need is a friend indeed.", arabic: "الصديق وقت الضيق."),
    ItemCard(english: "You're a true friend in need.", arabic: "أنت صديق حقيقي وقت الضيق."),
    ItemCard(english: "Thanks for being a friend in need.", arabic: "شكراً إنك صديق وقت الضيق."),
    ItemCard(english: "He helped me when I needed him most.", arabic: "هو ساعدني لما كنت محتاجه أكتر."),

    // ===================== إضافات - جمل مع Job =====================
    ItemCard(english: "I'm looking for a job.", arabic: "أبحث عن وظيفة."),
    ItemCard(english: "I was hoping you could help me find a job.", arabic: "كنت أتمنى أن تساعدني ألاقي وظيفة."),
    ItemCard(english: "What kind of job are you interested in?", arabic: "أي نوع من الوظائف أنت مهتم بها؟"),
    ItemCard(english: "I don't know if they're hiring.", arabic: "مش عارف إذا كانوا بيوظفوا."),
    ItemCard(english: "I'll find out if they have any openings.", arabic: "هكتشف إذا كان عندهم وظائف شاغرة."),
    ItemCard(english: "I'll talk to my boss in the morning.", arabic: "هتكلم مع مديري الصبح."),

    // ===================== إضافات - جمل مع Waiting =====================
    ItemCard(english: "I'm waiting to hear from you.", arabic: "أنا في انتظار ردك."),
    ItemCard(english: "I'll get back to you soon.", arabic: "هرد عليك قريب."),
    ItemCard(english: "Let me know what happens.", arabic: "قوللي إيه اللي يحصل."),
    ItemCard(english: "I'll wait for your call.", arabic: "هستنى مكالمتك."),

    // ===================== إضافات - جمل متنوعة =====================
    ItemCard(english: "Sure, how can I help?", arabic: "بالتأكيد، كيف يمكنني مساعدتك؟"),
    ItemCard(english: "No problem at all.", arabic: "مفيش أي مشكلة."),
    ItemCard(english: "Can't you be a little more specific?", arabic: "ممكن تكون أكثر تحديداً؟"),
    ItemCard(english: "I wish I could, man.", arabic: "أتمنى لو كنت أستطيع يا راجل."),
    ItemCard(english: "Anything you think that I can do will be fine.", arabic: "أي حاجة تعتقد إني أقدر أعملها هتكون كويسة."),
    ItemCard(english: "That bad, ha?", arabic: "للهذه الدرجة، ها؟"),
    ItemCard(english: "Good man.", arabic: "راجل طيب."),
    ItemCard(english: "Of course. Anything else you need me to do?", arabic: "بالتأكيد. أي حاجة تانية محتاجني أعملها؟"),
    ItemCard(english: "Alright, take care.", arabic: "حسناً، اعتن بنفسك."),
    ItemCard(english: "Yeah, you too.", arabic: "أجل، وأنت أيضاً."),
    ItemCard(english: "It's great to hear from you.", arabic: "سعيد إني سمعت منك."),
    ItemCard(english: "I hope everything works out.", arabic: "آمل إن كل حاجة تتظبط."),
    ItemCard(english: "I'll keep my fingers crossed.", arabic: "هحافظ على تفاؤلي."),
    ItemCard(english: "Thanks for your help, I really appreciate it.", arabic: "شكراً على مساعدتك، أنا حقاً أقدرها."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Conversation Ep13 - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


