class ConversationEp14CompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===================== جمل من الشرح =====================
    ItemCard(english: "\"Yo Mark, What up man?\" Yo is slang and we use it for 3 main purposes.", arabic: "\"يو مارك، إيه الأخبار يا راجل؟\" Yo هي عامية ونستخدمها لثلاثة أغراض رئيسية."),
    ItemCard(english: "First usage of Yo is to greet someone. It's like saying \"hello\".", arabic: "الاستخدام الأول لـ Yo هو تحية شخص ما. إنها مثل قول \"hello\"."),
    ItemCard(english: "Second usage of Yo is to attract someone's attention.", arabic: "الاستخدام الثاني لـ Yo هو جذب انتباه شخص ما."),
    ItemCard(english: "You want someone to pay attention to you. Or perhaps someone is not looking at you and you want them to turn their heads to your direction.", arabic: "تريد أن ينتبه شخص ما إليك. أو ربما شخص لا ينظر إليك وتريد أن يستدير في اتجاهك."),
    ItemCard(english: "Yo in this usage, it is equal to saying \"hey\".", arabic: "Yo في هذا الاستخدام تعادل قول \"hey\"."),
    ItemCard(english: "Third usage of Yo is to express excitement. It's like saying \"Wow\".", arabic: "الاستخدام الثالث لـ Yo هو التعبير عن الحماس. إنها مثل قول \"واو\"."),
    ItemCard(english: "\"I was about to call you? What's the word?\"", arabic: "\"كنت على وشك الاتصال بك؟ أخبارك يا صديقي.\""),
    ItemCard(english: "What's the word is slang and we use it to ask someone how they are doing. It's like saying \"how are you\", \"howdy\", \"how is it going\", \"what's up\", \"what's happening\", \"how are things\" and all of that.", arabic: "What's the word هي عامية ونستخدمها للسؤال عن حال شخص ما. إنها مثل قول \"كيف حالك\"، \"howdy\"، \"كيف تسير الأمور\"، \"what's up\"، \"ماذا يحدث\"، \"كيف الأمور\" وكل ذلك."),
    ItemCard(english: "A: All good. Got some good news for you by the way. B: Brilliant. Spill it, Jay.", arabic: "أ: كل شيء بخير. بالمناسبة لدي أخبار جيدة لك. ب: رائع. قولها يا جاي."),
    ItemCard(english: "Brilliant is a word that we can use to express happiness or satisfaction. Use it the same way you use, awesome, great, amazing.", arabic: "Brilliant كلمة يمكننا استخدامها للتعبير عن السعادة أو الرضا. استخدمها بنفس طريقة awesome، great، amazing."),
    ItemCard(english: "Spill it is slang for \"talk\" - \"say it\".", arabic: "Spill it هي عامية تعني \"تحدث\" - \"قلها\"."),
    ItemCard(english: "We can also use another word similar to this and say \"spit it out\".", arabic: "يمكننا أيضاً استخدام كلمة أخرى مشابهة ونقول \"spit it out\"."),
    ItemCard(english: "Of course we don't want the person to eject saliva out of their mouths, but we want them to hurry up and talk.", arabic: "بالطبع لا نريد أن يخرج الشخص اللعاب من فمه، لكننا نريده أن يسرع ويتحدث."),
    ItemCard(english: "Jay is a nickname for Jack.", arabic: "Jay هو لقب لـ Jack."),
    ItemCard(english: "\"Thanks a lot, bud. Did he say he has an open position?\"", arabic: "\"شكراً جزيلاً يا صاحبي. هل قال أن لديه وظيفة شاغرة؟\""),
    ItemCard(english: "The word bud is short for buddy. Buddy means \"close friend\".", arabic: "كلمة bud هي اختصار لـ buddy. Buddy تعني \"صديق مقرب\"."),
    ItemCard(english: "An open position is a vacant job.", arabic: "الوظيفة الشاغرة هي وظيفة خالية."),
    ItemCard(english: "A vacant job means a job that nobody is filling at the moment, so it's available for someone to come and take it.", arabic: "الوظيفة الشاغرة تعني وظيفة لا يشغلها أحد في الوقت الحالي، لذا فهي متاحة لشخص ما ليأتي ويأخذها."),
    ItemCard(english: "\"No, he didn't mention any vacancy at the moment.\" The word vacancy is the noun from vacant.", arabic: "\"لا، لم يذكر أي شاغر في الوقت الحالي.\" كلمة vacancy هي الاسم من vacant."),

    // ===================== جمل المحادثة - Part 1 =====================
    ItemCard(english: "Yo Mark, What up man?", arabic: "يو مارك، أخبارك يا صديقي."),
    ItemCard(english: "Hey Jack, I was about to call you? What's the word?", arabic: "أهلاً جاك، كنت على وشك الاتصال بك؟ أخبارك يا صديقي."),
    ItemCard(english: "All good. Got some good news for you by the way.", arabic: "بخير. بالمناسبة لدي أخبار جيدة لك."),
    ItemCard(english: "Brilliant. Spill it, Jay.", arabic: "رائع. قولها يا جاي."),
    ItemCard(english: "Okay, I talked to my boss. I will text you his phone number.", arabic: "حسناً، لقد تكلمت مع رئيسي بالعمل. سوف أرسل لك رقم هاتفه."),
    ItemCard(english: "Thanks a lot, bud. Did he say he has an open position?", arabic: "شكراً جزيلاً يا صاحبي. هل قال أن لديه وظيفة شاغرة؟"),
    ItemCard(english: "No, he didn't mention any vacancy at the moment, but he said he would talk to you.", arabic: "لا، لم يذكر شيئاً عن وظائف شاغرة حالياً، ولكنه قال أنه سيتحدث إليك."),
    ItemCard(english: "That's great! Hey, thanks again man.", arabic: "هذا رائع! شكراً لك مجدداً يا رجل."),

    // ===================== جمل المحادثة - Part 2 =====================
    ItemCard(english: "Sure. You know, you should also go online to look for work.", arabic: "بكل تأكيد، أتعلم، يجب عليك البحث عبر الإنترنت عن وظيفة."),
    ItemCard(english: "Online? Where?", arabic: "عبر الإنترنت؟ أين؟"),
    ItemCard(english: "There are many job search websites.", arabic: "هناك العديد من المواقع الإلكترونية للبحث عن وظائف."),
    ItemCard(english: "Cool. Do you know any by name?", arabic: "رائع. هل تعرف أي أسماء منها؟"),
    ItemCard(english: "Just Google \"Jobs in Cairo\" and you'll find some.", arabic: "فقط استخدم محرك البحث جوجل ابحث عن \"وظائف بالقاهرة\" وستجد البعض منها."),
    ItemCard(english: "Okay, I'll try that when I get home.", arabic: "حسناً. سأجرب حين أصل البيت."),
    ItemCard(english: "You can do it on your smartphone, you know.", arabic: "أتدري، يمكنك البحث من خلال هاتفك الذكي."),
    ItemCard(english: "I know, but I think it's better at home, thanks again.", arabic: "أعلم هذا، لكني أعتقد أنه من الأفضل البحث بالمنزل، شكراً مجدداً."),

    // ===================== إضافات - جمل مع Yo =====================
    ItemCard(english: "Yo, what's up?", arabic: "يو، إيه الأخبار؟"),
    ItemCard(english: "Yo! Over here!", arabic: "يو! هنا!"),
    ItemCard(english: "Yo, that's amazing!", arabic: "يو، ده مذهل!"),
    ItemCard(english: "Yo Mark, what's good?", arabic: "يو مارك، إيه الأخبار الحلوة؟"),

    // ===================== إضافات - جمل مع What's the word? =====================
    ItemCard(english: "What's the word?", arabic: "إيه الأخبار؟ / كيف حالك؟"),
    ItemCard(english: "What's the word, man?", arabic: "إيه الأخبار يا راجل؟"),
    ItemCard(english: "Long time no see! What's the word?", arabic: "بقالي كتير مشفتكش! إيه الأخبار؟"),
    ItemCard(english: "What's the word on the street?", arabic: "إيه الأخبار على الساحة؟"),

    // ===================== إضافات - جمل مع Brilliant =====================
    ItemCard(english: "Brilliant! That's great news.", arabic: "رائع! دي أخبار عظيمة."),
    ItemCard(english: "That's a brilliant idea.", arabic: "دي فكرة رائعة."),
    ItemCard(english: "You did a brilliant job.", arabic: "عملت شغل رائع."),
    ItemCard(english: "Brilliant, let's do it!", arabic: "رائع، يلا نعملها!"),

    // ===================== إضافات - جمل مع Spill it / Spit it out =====================
    ItemCard(english: "Spill it, Jay!", arabic: "قولها يا جاي!"),
    ItemCard(english: "Come on, spill the beans!", arabic: "يلا، قول السر!"),
    ItemCard(english: "Spit it out, I'm waiting!", arabic: "قولها بسرعة، أنا مستني!"),
    ItemCard(english: "Just spill it already!", arabic: "قولها خلاص!"),

    // ===================== إضافات - جمل مع Bud / Buddy =====================
    ItemCard(english: "Thanks a lot, bud.", arabic: "شكراً جزيلاً يا صاحبي."),
    ItemCard(english: "Hey buddy, how's it going?", arabic: "يا صاحبي، كيف الأمور؟"),
    ItemCard(english: "He's my best buddy.", arabic: "هو أفضل صديق ليا."),
    ItemCard(english: "Thanks for your help, buddy.", arabic: "شكراً على مساعدتك يا صاحبي."),

    // ===================== إضافات - جمل مع Open position / Vacancy =====================
    ItemCard(english: "Did he say he has an open position?", arabic: "هل قال أن لديه وظيفة شاغرة؟"),
    ItemCard(english: "He didn't mention any vacancy at the moment.", arabic: "لم يذكر أي شاغر في الوقت الحالي."),
    ItemCard(english: "There's an open position in the marketing department.", arabic: "في وظيفة شاغرة في قسم التسويق."),
    ItemCard(english: "Is there any vacancy in your company?", arabic: "في أي شاغر في شركتك؟"),
    ItemCard(english: "The position is still vacant.", arabic: "الوظيفة لسه شاغرة."),

    // ===================== إضافات - جمل مع Job search =====================
    ItemCard(english: "There are many job search websites.", arabic: "هناك العديد من المواقع الإلكترونية للبحث عن وظائف."),
    ItemCard(english: "You should also go online to look for work.", arabic: "لازم كمان تبحث أونلاين عن وظيفة."),
    ItemCard(english: "Just Google \"Jobs in Cairo\" and you'll find some.", arabic: "فقط ابحث في جوجل عن \"وظائف بالقاهرة\" وهتلاقي بعضها."),
    ItemCard(english: "LinkedIn is a great job search website.", arabic: "لينكدإن موقع عظيم للبحث عن وظائف."),
    ItemCard(english: "I found my job on a job search website.", arabic: "لقيت شغلي على موقع بحث عن وظائف."),

    // ===================== إضافات - جمل مع Online =====================
    ItemCard(english: "Online? Where?", arabic: "عبر الإنترنت؟ أين؟"),
    ItemCard(english: "You can do it on your smartphone.", arabic: "ممكن تعملها من موبايلك."),
    ItemCard(english: "I'll try that when I get home.", arabic: "هجربها لما أوصل البيت."),
    ItemCard(english: "I think it's better at home.", arabic: "أعتقد إنها أحسن في البيت."),
    ItemCard(english: "I do everything online these days.", arabic: "أنا بعمل كل حاجة أونلاين الأيام دي."),

    // ===================== إضافات - جمل مع Text / Phone number =====================
    ItemCard(english: "I will text you his phone number.", arabic: "هبعتلك رقم تليفونه في رسالة."),
    ItemCard(english: "Can you text me the address?", arabic: "ممكن تبعتلي العنوان في رسالة؟"),
    ItemCard(english: "I'll send you a text later.", arabic: "هبعتلك رسالة بعدين."),
    ItemCard(english: "What's your phone number?", arabic: "إيه رقم تليفونك؟"),

    // ===================== إضافات - جمل مع Thanks =====================
    ItemCard(english: "Thanks a lot, bud.", arabic: "شكراً جزيلاً يا صاحبي."),
    ItemCard(english: "That's great! Hey, thanks again man.", arabic: "ده رائع! شكراً لك مجدداً يا رجل."),
    ItemCard(english: "Thanks again for your help.", arabic: "شكراً مجدداً على مساعدتك."),
    ItemCard(english: "I really appreciate it.", arabic: "أنا حقاً أقدرها."),
    ItemCard(english: "Thanks a million!", arabic: "شكراً مليون مرة!"),

    // ===================== إضافات - جمل متنوعة =====================
    ItemCard(english: "All good.", arabic: "كل شيء بخير."),
    ItemCard(english: "Got some good news for you.", arabic: "عندي أخبار جيدة ليك."),
    ItemCard(english: "I was about to call you.", arabic: "كنت على وشك أتصل بيك."),
    ItemCard(english: "I talked to my boss.", arabic: "اتكلمت مع مديري."),
    ItemCard(english: "He said he would talk to you.", arabic: "قال إنه هيتكلم معاك."),
    ItemCard(english: "That's great news!", arabic: "دي أخبار عظيمة!"),
    ItemCard(english: "I'll try that when I get home.", arabic: "هجرب ده لما أوصل البيت."),
    ItemCard(english: "You can do it on your smartphone.", arabic: "ممكن تعملها من موبايلك."),
    ItemCard(english: "I think it's better at home.", arabic: "أعتقد إنها أحسن في البيت."),
    ItemCard(english: "Do you know any by name?", arabic: "تعرف أي أسماء منها؟"),
    ItemCard(english: "Just Google it.", arabic: "ابحث عنها في جوجل."),
    ItemCard(english: "You'll find some.", arabic: "هتلاقي بعضها."),
    ItemCard(english: "Thanks again man.", arabic: "شكراً مجدداً يا راجل."),
    ItemCard(english: "To be continued...", arabic: "يتبع..."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Conversation Ep14 - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


