class ConversationEp15CompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===================== جمل من الشرح =====================
    ItemCard(english: "\"Man, Am I excited?\" That wasn't a real question.", arabic: "\"يا راجل، كم أنا متحمس!\" لم يكن سؤالاً حقيقياً."),
    ItemCard(english: "He is not actually saying \"Do you think I'm excited?\" or \"Do I look like I'm excited?\"", arabic: "هو لا يقول فعلاً \"هل تعتقد أني متحمس؟\" أو \"هل أبدو متحمساً؟\""),
    ItemCard(english: "No, he wasn't asking at all. So why did he say \"am I excited?\" instead of \"I am excited\"?", arabic: "لا، لم يكن يسأل على الإطلاق. فلماذا قال \"am I excited?\" بدلاً من \"I am excited\"؟"),
    ItemCard(english: "He could have said that, but it's more common to express excitement in the form of a question.", arabic: "كان يمكنه قول ذلك، لكن من الشائع أكثر التعبير عن الحماس في صيغة سؤال."),
    ItemCard(english: "Example: Wow, it's so beautiful. > Wow, is it beautiful?", arabic: "مثال: واو، إنها جميلة جداً. > واو، هل هي جميلة؟"),
    ItemCard(english: "My god, he is so annoying. > My god, is he annoying?", arabic: "يا إلهي، إنه مزعج جداً. > يا إلهي، هل هو مزعج؟"),
    ItemCard(english: "\"It's an internship for a tech company.\"", arabic: "\"إنها فترة تدريب لشركة تقنية.\""),
    ItemCard(english: "An internship is when you get a position in a company as a student or a trainee. You work there sometimes without getting paid because you want to learn and gain more experience.", arabic: "فترة التدريب هي عندما تحصل على منصب في شركة كطالب أو متدرب. تعمل هناك أحياناً بدون أجر لأنك تريد التعلم واكتساب المزيد من الخبرة."),
    ItemCard(english: "\"Wow, that's impressive. I hope you get it. Fingers crossed.\"", arabic: "\"واو، هذا مبهر. أتمنى أن تحصل عليها. أدعو لك.\""),
    ItemCard(english: "We can say another word for \"impressive\" like (awesome, admirable, spectacular or excellent).", arabic: "يمكننا قول كلمة أخرى بدلاً من \"impressive\" مثل (awesome، admirable، spectacular أو excellent)."),
    ItemCard(english: "\"Fingers crossed\" This is a hand gesture that we commonly use to wish someone good luck, it's like saying \"I wish you good luck\".", arabic: "\"Fingers crossed\" هذه إشارة يد نستخدمها بشكل شائع لنتمنى لشخص حظاً سعيداً، إنها مثل قول \"أتمنى لك حظاً سعيداً\"."),
    ItemCard(english: "\"We're doing mock interviews.\"", arabic: "\"نحن نتدرب بطريقة مماثلة تماماً للمقابلات الفعلية.\""),
    ItemCard(english: "The word \"mock\" can be used to mean \"laugh at someone or something\" or \"to create something similar to the original object. To make a good copy of it (a replica)\".", arabic: "كلمة \"mock\" يمكن استخدامها بمعنى \"السخرية من شخص أو شيء\" أو \"إنشاء شيء مشابه للشيء الأصلي. لعمل نسخة جيدة منه (نسخة طبق الأصل)\"."),
    ItemCard(english: "Example: It's not okay to mock and disrespect others. Mock = laugh at or tease", arabic: "مثال: لا بأس في السخرية وعدم احترام الآخرين. Mock = يسخر أو يضايق"),
    ItemCard(english: "We always give students mock exams. Mock = replica - a similar copy", arabic: "نحن دائماً نعطي الطلاب امتحانات تجريبية. Mock = نسخة طبق الأصل - نسخة مشابهة"),
    ItemCard(english: "\"That's strange because you're the only one I know who doesn't use fillers in his speech.\"", arabic: "\"هذا غريب لأنك الوحيد الذي أعرفه ولا يستخدم كلمات الحشو في كلامه.\""),
    ItemCard(english: "The word fillers, as the name suggests is something we put in a place to fill it.", arabic: "كلمة fillers، كما يوحي الاسم، هي شيء نضعه في مكان لملئه."),
    ItemCard(english: "When you talk, sometimes we need to think of the next word or we need to choose words carefully. We will end up having a gap in our speech. To fill this gap we use what we call \"fillers\".", arabic: "عندما تتحدث، أحياناً نحتاج للتفكير في الكلمة التالية أو نحتاج لاختيار الكلمات بعناية. سننتهي بوجود فراغ في كلامنا. لملء هذا الفراغ نستخدم ما نسميه \"fillers\"."),
    ItemCard(english: "Fillers words like (you know - uh - mmm - like) we use them to avoid stopping when we talk.", arabic: "كلمات الحشو مثل (you know - uh - mmm - like) نستخدمها لتجنب التوقف عندما نتحدث."),
    ItemCard(english: "Nowadays teenagers overuse fillers in their speech. It's disgusting.", arabic: "في الوقت الحاضر، يفرط المراهقون في استخدام كلمات الحشو في كلامهم. إنه مقزز."),
    ItemCard(english: "I was like you know happy but he was like you know ummm not so much and then we you know told him like come on.", arabic: "كنت مثل تعرف سعيد لكنه كان مثل تعرف ممم ليس كثيراً وبعدها نحن تعرف قلنا له مثل يلا."),
    ItemCard(english: "It's just hurtful to hear. So, it's okay to use fillers every now and then but don't over do it.", arabic: "إنه مؤلم للسمع. لذا، لا بأس في استخدام كلمات الحشو من وقت لآخر ولكن لا تبالغ فيها."),
    ItemCard(english: "\"Let me just stop you there. I was just being sarcastic. Your sister is right, you overuse fillers.\"", arabic: "\"دعني أوقفك عند هذا الحد. كنت فقط أسخر. أختك على حق، أنت تفرط في استخدام كلمات الحشو.\""),
    ItemCard(english: "His friend was just using sarcasm. He was being sarcastic. Sarcasm is when you say the opposite of what you want to say in order to make fun of someone.", arabic: "صديقه كان يستخدم السخرية فقط. كان يسخر. السخرية هي عندما تقول عكس ما تريد قوله بهدف السخرية من شخص ما."),
    ItemCard(english: "Example: You look very tired in the morning and you keep yawning. I look at you and say; wow, I love your energy in the morning.", arabic: "مثال: تبدو متعباً جداً في الصباح وتستمر في التثاؤب. أنظر إليك وأقول: واو، أحب طاقتك في الصباح."),
    ItemCard(english: "The question is: do I mean it? Do I love your energy? No, it is the opposite of what I want to say. You have no energy. So this is sarcasm and I was being sarcastic.", arabic: "السؤال هو: هل أعنيها؟ هل أحب طاقتك؟ لا، إنه عكس ما أريد قوله. ليس لديك طاقة. لذا هذه سخرية وكنت أسخر."),

    // ===================== جمل المحادثة - Part 1 =====================
    ItemCard(english: "Man, Am I excited? I've got my first job interview.", arabic: "يا رجل، كم أنا متحمس! لقد حصلت على أول مقابلة عمل لي."),
    ItemCard(english: "Interview for what?", arabic: "مقابلة عمل من أجل ماذا؟"),
    ItemCard(english: "You know, it's an internship for a big company.", arabic: "أتعلم، إنها فترة تدريب لدى شركة كبيرة."),
    ItemCard(english: "Wow, that's impressive. I hope you get it. Fingers crossed.", arabic: "هذا رائع، أتمنى حصولك عليها. دعواتي لك من أجل ذلك."),
    ItemCard(english: "Well, thanks. I'm preparing for the interview by - you know - practicing with my sister.", arabic: "شكراً، أنا أحضر لمقابلة العمل عن طريق التدرب مع أختي."),
