    // ===================== جمل المحادثة - Part 2 =====================
    ItemCard(english: "We're doing mock interviews.", arabic: "نحن نتدرب بطريقة مماثلة تماماً للمقابلات الفعلية."),
    ItemCard(english: "Is it helpful?", arabic: "هل هذه الطريقة مفيدة؟"),
    ItemCard(english: "It sure is. She recorded our first interview, and pointed out things that umm - you know - I should avoid.", arabic: "بالتأكيد. قامت بتسجيل أولى مقابلتنا، وأشارت إلى ممم أشياء علي تجنبها."),
    ItemCard(english: "What are some of the things she saw?", arabic: "أخبرني ما هي بعض ملاحظاتها."),
    ItemCard(english: "She said that I said, \"You know\" too much, and that I looked nervous.", arabic: "لقد قالت لي إني أتكلم أكثر مما ينبغي، وأن التوتر ظاهر علي."),
    ItemCard(english: "Oh really, that's strange because you're the only one I know who doesn't use fillers in his speech.", arabic: "حقاً، هذا يبدو غريباً لأنك أنت الوحيد في من أعرفهم الذي يتحدث دون التوقف أثناء كلامه."),

    // ===================== جمل المحادثة - Part 3 =====================
    ItemCard(english: "I know, right? I was like no, I don't do that, but she was kind of like, yeah you do.", arabic: "أعرف، أليس كذلك؟ كنت مثل لا، أنا لا أفعل ذلك، لكنها كانت نوعاً ما مثل، أجل أنت تفعل."),
    ItemCard(english: "Dude, dude. Let me just stop you there. I was just being sarcastic. Your sister is right, you overuse fillers.", arabic: "يا صاحبي، يا صاحبي. دعني أوقفك عند هذا الحد. كنت فقط أسخر. أختك على حق، أنت تفرط في استخدام كلمات الحشو."),
