class ConversationEp16WordsScreen extends StatelessWidget {
  final List<LearningCard> Cards = [
    // ===================== كلمات أساسية =====================
    LearningCard(primaryText: "Good morning", secondaryText: "صباح الخير"),
    LearningCard(primaryText: "Robert", secondaryText: "روبرت (اسم)"),
    LearningCard(primaryText: "Stevens", secondaryText: "ستيفنز (اسم)"),
    LearningCard(primaryText: "Mark", secondaryText: "مارك (اسم)"),
    LearningCard(primaryText: "Jones", secondaryText: "جونز (اسم)"),
