class ConversationEp16CompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===================== جمل من الشرح =====================
    ItemCard(english: "\"I like working with people. I'm a great people person.\"", arabic: "\"أحب العمل مع الناس. أنا شخص اجتماعي.\""),
    ItemCard(english: "A people person is somebody who is very good at interacting with people. They enjoy being around people.", arabic: "الشخص الاجتماعي هو شخص بارع جداً في التفاعل مع الناس. يستمتع بوجوده بين الناس."),
    ItemCard(english: "Some of us are like this, it comes naturally to some of us to know what to say and how to say it. But for some, interaction with people needs a little extra effort.", arabic: "البعض منا هكذا، يأتي بشكل طبيعي للبعض معرفة ما يقولون وكيف يقولونه. لكن للبعض الآخر، يحتاج التفاعل مع الناس إلى جهد إضافي."),
    ItemCard(english: "To be a good team player and blend in, we all need to learn how to make others comfortable talking to us.", arabic: "لكي تكون لاعب فريق جيد وتندمج، نحتاج جميعاً أن نتعلم كيف نجعل الآخرين مرتاحين في التحدث معنا."),
    ItemCard(english: "If you make people comfortable coming to you. We call you approachable.", arabic: "إذا جعلت الناس مرتاحين في القدوم إليك، نسميك approachable (ودود / سهل التعامل)."),
    ItemCard(english: "If you're approachable, you're welcoming, you're friendly and easy to talk to. It's a very good skill.", arabic: "إذا كنت approachable، فأنت مرحب، ودود، وسهل التحدث معك. إنها مهارة جيدة جداً."),
    ItemCard(english: "\"I'm very responsible and I always aspire to meet the expectations that my managers have of me.\"", arabic: "\"أنا مسؤول جداً وأطمح دائماً لتلبية توقعات مدرائي مني.\""),
    ItemCard(english: "The word aspire is a little similar to the word hope or desire.", arabic: "كلمة aspire تشبه قليلاً كلمة hope أو desire."),
    ItemCard(english: "I aspire to do something. = I have a desire to do it or I hope to achieve it.", arabic: "أطمح لفعل شيء ما. = لدي رغبة في فعله أو آمل في تحقيقه."),
    ItemCard(english: "\"Haha you bet but, don't worry. I've seen worse.\"", arabic: "\"هاها بالتأكيد، لكن لا تقلق. لقد رأيت أسوأ من ذلك.\""),
    ItemCard(english: "You bet is slang and means \"yes\", \"you're right\", \"Of course,\" and \"totally\".", arabic: "You bet هي عامية وتعني \"نعم\"، \"أنت على حق\"، \"بالطبع\"، و \"تماماً\"."),
    ItemCard(english: "Example: Person A invites you to dinner. After dinner he asks you if you enjoyed the meal. You can say \"You bet\". It means. \"Yes, I did\".", arabic: "مثال: شخص أ يدعوك للعشاء. بعد العشاء يسألك إذا استمتعت بالوجبة. يمكنك قول \"You bet\". تعني \"نعم، استمتعت\"."),
    ItemCard(english: "\"Sorry. I just like to be always prepared and hey, doesn't this itself show my devotion?\"", arabic: "\"آسف. أنا فقط أحب أن أكون مستعداً دائماً، ويا، ألا يظهر هذا بحد ذاته إخلاصي؟\""),
    ItemCard(english: "The word devotion here means \"loyalty towards something\".", arabic: "كلمة devotion هنا تعني \"الولاء لشيء ما\"."),
    ItemCard(english: "If you love something so much and you're very loyal to it. We say \"you're devoted\".", arabic: "إذا أحببت شيئاً كثيراً وكنت وفياً له جداً، نقول \"أنت مخلص / متفانٍ\"."),
    ItemCard(english: "\"Not to toot my own horn.\" This is a phrase used especially in America and Canada.", arabic: "\"ليس غروراً.\" هذه عبارة تُستخدم خاصة في أمريكا وكندا."),
    ItemCard(english: "It means, to talk about yourself and say very good things. It's like the word \"brag\".", arabic: "تعني أن تتحدث عن نفسك وتقول أشياء جيدة جداً. إنها مثل كلمة \"brag\" (يتفاخر)."),
    ItemCard(english: "\"Wow, ok. Off the top of my head, I think my main weakness is that I don't tolerate sloppy work.\"", arabic: "\"واو، حسناً. من رأس مباشرة، أعتقد أن نقطة ضعفي الأساسية هي أنني لا أتحمل العمل المهمل.\""),
    ItemCard(english: "\"Off the top of my head\" means. I will just say what comes to my mind without thinking first. I will not give any careful thoughts.", arabic: "\"من رأس مباشرة\" تعني أنني سأقول فقط ما يخطر ببالي دون تفكير أولاً. لن أعطي أي أفكار مدروسة بعناية."),
    ItemCard(english: "The word \"tolerate\" means, to allow. The word \"sloppy\" means, careless or disorganized.", arabic: "كلمة \"tolerate\" تعني يسمح. كلمة \"sloppy\" تعني مهمل أو غير منظم."),
    ItemCard(english: "\"... you are a perfectionist or any of that bullsh, please just save it.\" Bullsh is a short way of saying \"Bullshit\".", arabic: "\"... أنت مثالي أو أي من هذا الهراء، من فضلك احتفظ به.\" Bullsh هي طريقة مختصرة لقول \"Bullshit\" (هراء)."),

    // ===================== جمل المحادثة - Part 1 =====================
    ItemCard(english: "Good morning. I'm Robert Stevens.", arabic: "صباح الخير. أنا روبرت ستيفنز."),
    ItemCard(english: "Good morning, Mr. Stevens. My name is Mark Jones.", arabic: "صباح الخير سيد ستيفنز. اسمي مارك جونز."),
    ItemCard(english: "Please have a seat and let's get started.", arabic: "تفضل بالجلوس ودعنا نبدأ."),
    ItemCard(english: "Thank you, Mr. Stevens.", arabic: "شكراً لك سيد ستيفنز."),
    ItemCard(english: "Please call me Robert, and I'll call you Mark. We are informal here.", arabic: "رجاءً نادني روبرت، وأنا سوف أناديك مارك. نحن ننادي بعضنا بشكل غير رسمي."),
    ItemCard(english: "That's good to know, Robert. Thanks.", arabic: "من الجيد معرفة هذا يا روبرت. شكراً لك."),

    // ===================== جمل المحادثة - Part 2 =====================
    ItemCard(english: "Sure, was it easy to find the office?", arabic: "على الرحب، كان من السهل عليك الوصول للمكتب؟"),
    ItemCard(english: "Yeah, it was pretty easy. Plus, I always use GPS.", arabic: "نعم، كان سهلاً، بالإضافة إلى أني دائماً أستخدم GPS."),
    ItemCard(english: "Alright, why don't we start by you telling me a little about yourself?", arabic: "حسناً، لماذا لا نبدأ بأن تخبرني قليلاً عن نفسك؟"),
    ItemCard(english: "Sure. My name is Mark. I graduated from Cairo University in 2016. I'm doing my master's degree in business administration. I like working with people. I'm a great people person. I'm very responsible and I always aspire to meet the expectations that my managers have of me.", arabic: "بالتأكيد. اسمي مارك. تخرجت من جامعة القاهرة عام 2016. أدرس الآن في مرحلة الماجستير وموضوع دراستي هو إدارة الأعمال. أحب العمل مع الناس. أنا شخص اجتماعي. أنا مسؤول وأطمح دوماً أن أكون على مستوى توقعات مديريني."),

    // ===================== جمل المحادثة - Part 3 =====================
    ItemCard(english: "I can tell that your practiced saying that.", arabic: "أنا متأكد من أنك قد تدربت على قول هذا."),
    ItemCard(english: "Was it that obvious?", arabic: "أكان الأمر بهذا الوضوح؟"),
    ItemCard(english: "Haha you bet but, don't worry. I've seen worse.", arabic: "هاهاها، بالتأكيد، لا تقلق لقد رأيت ما هو أسوأ."),
    ItemCard(english: "Sorry. I just like to be always prepared and hey, doesn't this itself show my devotion?", arabic: "آسف. أود فقط أن أكون مستعداً دائماً، ألا يظهر هذا ذاته إخلاصي؟"),
    ItemCard(english: "You're right, it kinda does.", arabic: "أنت على حق، بالفعل يشير إلى حد ما."),
    ItemCard(english: "Not to toot my own horn, but I really think that I'm an excellent candidate for the job.", arabic: "ليس غروراً، بالنسبة لي أعتقد أني المرشح المثالي لهذه الوظيفة."),

    // ===================== جمل المحادثة - Part 4 =====================
    ItemCard(english: "I see you have two years of experience. Can you tell me a little about that?", arabic: "أرى أن لديك سنتين من الخبرة. أيمكنك أن تحدثني عن ذلك؟"),
    ItemCard(english: "Oh, yes. I worked in the mailroom at ABC Corporation last year.", arabic: "نعم، عملت بغرفة البريد لدى مؤسسة ABC في العام الماضي."),
    ItemCard(english: "Go on, please.", arabic: "استمر رجاءً."),
    ItemCard(english: "It was a temporary job, but I gained a lot of experience.", arabic: "كان عملاً مؤقتاً، ولكني حصلت على العديد من الخبرات."),
    ItemCard(english: "Excellent! We are always looking for someone with experience.", arabic: "ممتاز! نحن دائماً نبحث عن ذوي الخبرة."),
    ItemCard(english: "I think this experience will help me blend into a job working here.", arabic: "أعتقد أن هذه الخبرة ستساعدني على الاندماج في عملي هنا."),

    // ===================== جمل المحادثة - Part 5 =====================
    ItemCard(english: "What are your weaknesses, Mark? Before you say anything. Please bear in mind that I heard all the ideal answers, so if you're going to tell me that your weaknesses are that you're very patient or that you take up too many tasks or you are a perfectionist or any of that bullsh, please just save it. Ok?", arabic: "ما هي نقاط ضعفك يا مارك؟ قبل أن تقول أي شيء. من فضلك ضع في اعتبارك أني سمعت كل الأجابات النموذجية، لذا إذا كنت ستخبرني أن نقاط ضعفك هي أنك صبور للغاية أو أنك تتولى الكثير من المهام أو أنك كامل أو أي من هذه الهراء، رجاءً احتفظ به. حسناً؟"),
    ItemCard(english: "Wow, ok. Off the top of my head, I think my main weakness is that I don't tolerate sloppy work. Sometimes I come across as a tough person but that's how you can lead.", arabic: "حسناً، أول ما خطر ببالي دون تفكير، أعتقد أن نقاط ضعفي الأساسية هي أني لا أتساهل مع التخاذل في العمل. أحياناً أكون شخص شديد ولكن هذا ما يتطلبه الأمر حتى تستطيع القيادة."),
    ItemCard(english: "Alright, Mark. I like this answer.", arabic: "حسناً يا مارك، أعجبتني هذه الإجابة."),
    ItemCard(english: "Thank you, Sir.", arabic: "شكراً لك سيدي."),
    ItemCard(english: "Do you have any questions for me?", arabic: "هل لديك أي أسئلة لي؟"),
    ItemCard(english: "Well, I've already done my homework and learned everything I need to learn from the internet, but I would like to know when to expect a call from you.", arabic: "حسناً، لقد قمت بالفعل بأداء واجبي وتعلمت كل شيء أحتاج أن أتعلمه من الإنترنت، ولكن أود أن أعرف متى أتوقع مكالمة منكم."),

    // ===================== جمل المحادثة - Part 6 =====================
    ItemCard(english: "You'll be contacted by an HR representative within two weeks.", arabic: "سوف تتلقى اتصالاً من ممثل الموارد البشرية في خلال أسبوعين."),
    ItemCard(english: "Great, thanks again for having me.", arabic: "رائع، شكراً مجدداً على مقابلتي."),
    ItemCard(english: "Thanks for coming. Have a good day.", arabic: "شكراً لقدومك. أتمنى لك يوماً جيداً."),
    ItemCard(english: "You too, Sir.", arabic: "وأنت أيضاً سيدي."),

    // ===================== إضافات - جمل مع Interview =====================
    ItemCard(english: "Good morning, I'm here for the interview.", arabic: "صباح الخير، أنا هنا من أجل المقابلة."),
    ItemCard(english: "Please have a seat and let's get started.", arabic: "تفضل بالجلوس ودعنا نبدأ."),
    ItemCard(english: "Can you tell me a little about yourself?", arabic: "أيمكنك أن تخبرني قليلاً عن نفسك؟"),
    ItemCard(english: "Why do you want to work here?", arabic: "لماذا تريد العمل هنا؟"),
    ItemCard(english: "What are your strengths and weaknesses?", arabic: "ما هي نقاط قوتك وضعفك؟"),
    ItemCard(english: "Where do you see yourself in 5 years?", arabic: "أين ترى نفسك بعد 5 سنوات؟"),
    ItemCard(english: "Do you have any questions for me?", arabic: "هل لديك أي أسئلة لي؟"),

    // ===================== إضافات - جمل مع People person =====================
    ItemCard(english: "I'm a great people person.", arabic: "أنا شخص اجتماعي."),
    ItemCard(english: "She's a real people person.", arabic: "هي شخصية اجتماعية حقيقية."),
    ItemCard(english: "To be a good team player, you need to be a people person.", arabic: "لتكون لاعب فريق جيد، تحتاج أن تكون شخصاً اجتماعياً."),
    ItemCard(english: "Being a people person helps in this job.", arabic: "كونك شخصاً اجتماعياً يساعد في هذه الوظيفة."),

    // ===================== إضافات - جمل مع Aspire =====================
    ItemCard(english: "I always aspire to meet the expectations of my managers.", arabic: "أنا دائماً أطمح لتلبية توقعات مدرائي."),
    ItemCard(english: "She aspires to become a doctor.", arabic: "هي تطمح لتصبح طبيبة."),
    ItemCard(english: "We should all aspire to be better.", arabic: "كلنا يجب أن نطمح لنكون أفضل."),
    ItemCard(english: "He aspires to achieve great things.", arabic: "هو يطمح لتحقيق أشياء عظيمة."),

    // ===================== إضافات - جمل مع You bet =====================
    ItemCard(english: "You bet! I'd love to help.", arabic: "بالتأكيد! أود المساعدة."),
    ItemCard(english: "You bet, I'll be there.", arabic: "بالتأكيد، هكون هناك."),
    ItemCard(english: "You bet it was fun!", arabic: "بالتأكيد كانت ممتعة!"),
    ItemCard(english: "You bet I'll pass the exam.", arabic: "بالتأكيد هنجح في الامتحان."),

    // ===================== إضافات - جمل مع Toot my own horn =====================
    ItemCard(english: "Not to toot my own horn, but I really think that I'm an excellent candidate.", arabic: "ليس غروراً، لكني حقاً أعتقد أني مرشح ممتاز."),
    ItemCard(english: "I don't like to toot my own horn, but I did a great job.", arabic: "أنا مش بحب أتفاخر، بس عملت شغل عظيم."),
    ItemCard(english: "Not to toot my own horn, but I'm really good at this.", arabic: "مش تفاخر، بس أنا فعلاً كويس في ده."),
    ItemCard(english: "She's always tooting her own horn.", arabic: "هي دايماً بتتفاخر بنفسها."),

    // ===================== إضافات - جمل مع Off the top of my head =====================
    ItemCard(english: "Off the top of my head, I think my main weakness is that I don't tolerate sloppy work.", arabic: "أول ما خطر ببالي دون تفكير، أعتقد أن نقاط ضعفي الأساسية هي أني لا أتساهل مع التخاذل في العمل."),
    ItemCard(english: "Off the top of my head, I can think of three reasons.", arabic: "أول ما يخطر ببالي، أقدر أفكر في 3 أسباب."),
    ItemCard(english: "Off the top of my head, I don't remember his name.", arabic: "أول ما يخطر ببالي، مش فاكر اسمه."),
    ItemCard(english: "I can't give you an answer off the top of my head.", arabic: "مش قادر أديك إجابة من غير تفكير."),

    // ===================== إضافات - جمل مع Tolerate / Sloppy =====================
    ItemCard(english: "I don't tolerate sloppy work.", arabic: "لا أتساهل مع التخاذل في العمل."),
    ItemCard(english: "I can't tolerate this behavior.", arabic: "مش قادر أتحمل السلوك ده."),
    ItemCard(english: "She won't tolerate any mistakes.", arabic: "هي مش هتتحمل أي أخطاء."),
    ItemCard(english: "Sloppy work is not acceptable here.", arabic: "العمل المهمل مش مقبول هنا."),

    // ===================== إضافات - جمل مع Devotion =====================
    ItemCard(english: "Doesn't this itself show my devotion?", arabic: "ألا يظهر هذا بحد ذاته إخلاصي؟"),
    ItemCard(english: "His devotion to his work is impressive.", arabic: "إخلاصه لشغله مبهر."),
    ItemCard(english: "She showed great devotion to her family.", arabic: "هي أظهرت إخلاص كبير لعيلتها."),
    ItemCard(english: "Devotion is important in any job.", arabic: "الإخلاص مهم في أي وظيفة."),

    // ===================== إضافات - جمل مع HR representative =====================
    ItemCard(english: "You'll be contacted by an HR representative within two weeks.", arabic: "سوف تتلقى اتصالاً من ممثل الموارد البشرية في خلال أسبوعين."),
    ItemCard(english: "The HR representative will call you soon.", arabic: "ممثل الموارد البشرية هيتصل بيك قريب."),
    ItemCard(english: "I spoke to the HR representative yesterday.", arabic: "اتكلمت مع ممثل الموارد البشرية امبارح."),
    ItemCard(english: "HR representative handles all hiring.", arabic: "ممثل الموارد البشرية مسؤول عن كل التوظيف."),

    // ===================== إضافات - جمل متنوعة =====================
    ItemCard(english: "Thanks for having me.", arabic: "شكراً على استضافتي."),
    ItemCard(english: "Thanks for coming. Have a good day.", arabic: "شكراً لقدومك. أتمنى لك يوماً جيداً."),
    ItemCard(english: "You too, Sir.", arabic: "وأنت أيضاً سيدي."),
    ItemCard(english: "Was it easy to find the office?", arabic: "كان من السهل الوصول للمكتب؟"),
    ItemCard(english: "Yeah, it was pretty easy. Plus, I always use GPS.", arabic: "نعم، كان سهلاً، بالإضافة إلى أني دائماً أستخدم GPS."),
    ItemCard(english: "Why don't we start by you telling me a little about yourself?", arabic: "لماذا لا نبدأ بأن تخبرني قليلاً عن نفسك؟"),
    ItemCard(english: "I can tell that you practiced saying that.", arabic: "أنا متأكد من أنك قد تدربت على قول هذا."),
    ItemCard(english: "Was it that obvious?", arabic: "أكان الأمر بهذا الوضوح؟"),
    ItemCard(english: "Haha you bet but, don't worry. I've seen worse.", arabic: "هاهاها، بالتأكيد، لا تقلق لقد رأيت ما هو أسوأ."),
    ItemCard(english: "You're right, it kinda does.", arabic: "أنت على حق، بالفعل يشير إلى حد ما."),
    ItemCard(english: "Go on, please.", arabic: "استمر رجاءً."),
    ItemCard(english: "Excellent! We are always looking for someone with experience.", arabic: "ممتاز! نحن دائماً نبحث عن ذوي الخبرة."),
    ItemCard(english: "I think this experience will help me blend into a job working here.", arabic: "أعتقد أن هذه الخبرة ستساعدني على الاندماج في عملي هنا."),
    ItemCard(english: "Thank you, Sir.", arabic: "شكراً لك سيدي."),
    ItemCard(english: "Do you have any questions for me?", arabic: "هل لديك أي أسئلة لي؟"),
    ItemCard(english: "I've already done my homework and learned everything I need to learn from the internet.", arabic: "لقد قمت بالفعل بأداء واجبي وتعلمت كل شيء أحتاج أن أتعلمه من الإنترنت."),
    ItemCard(english: "I would like to know when to expect a call from you.", arabic: "أود أن أعرف متى أتوقع مكالمة منكم."),
    ItemCard(english: "Great, thanks again for having me.", arabic: "رائع، شكراً مجدداً على مقابلتي."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Conversation Ep16 - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}



