    ItemCard(english: "It's down a block on the right; can I show you the way?", arabic: "إنه في نهاية المربع على اليمين؛ ممكن أوريك الطريق؟"),
    ItemCard(english: "This will work out well. I'm getting hungry just thinking about it.", arabic: "ده هينجح كويس. أنا بجوع بمجرد التفكير فيه."),
    ItemCard(english: "Do you know a good locksmith?", arabic: "تعرف صانع أقفال كويس؟ (معرفة شخصية)"),
    ItemCard(english: "Do you know of a good locksmith?", arabic: "تسمع عن صانع أقفال كويس؟ (سماع فقط)"),
    ItemCard(english: "Let's have some lunch; do you know of a great restaurant somewhere?", arabic: "يلا نتغدى؛ تسمع عن مطعم عظيم في مكان ما؟"),
    ItemCard(english: "I'm hungry, too. What types of food sound good?", arabic: "أنا كمان جعان. أي أنواع من الأكل تبدو كويسة؟"),
    ItemCard(english: "Maybe just a quick sandwich, salad, or something.", arabic: "يمكن مجرد ساندويتش سريع، سلطة، أو حاجة."),
    ItemCard(english: "I have a great idea of where you might like to go.", arabic: "عندي فكرة عظيمة لمكان ممكن تحب تروحه."),
    ItemCard(english: "Can we walk there?", arabic: "ممكن نمشي هناك؟"),
    ItemCard(english: "It's on the second floor. May I join you?", arabic: "إنه في الطابق الثاني. ممكن أنضم ليك؟"),
    ItemCard(english: "Of course! Let's go.", arabic: "بالطبع! يلا بينا."),
    ItemCard(english: "Let's hurry. I'm starving!", arabic: "يلا نسرع. أنا بتضور جوعاً!"),

    // ===================== Ep7 =====================
    ItemCard(english: "Switch = Change = Shift.", arabic: "تبديل = تغيير = تحول."),
    ItemCard(english: "Of course. Did you?", arabic: "بالطبع. هل فعلت؟"),
    ItemCard(english: "That's sad, but have you gone to the movies recently?", arabic: "ده محزن، لكن هل ذهبت للسينما مؤخراً؟"),
    ItemCard(english: "That's a switch.", arabic: "ده تغيير مفاجئ."),
    ItemCard(english: "I'm serious, have you?", arabic: "أنا جدي، هل فعلت؟"),
    ItemCard(english: "No, I haven't. Why?", arabic: "لا، لم أفعل. لماذا؟"),
    ItemCard(english: "I really want to go to the movies this weekend.", arabic: "أنا حقاً أريد الذهاب للسينما عطلة الأسبوع دي."),
    ItemCard(english: "So. Go then.", arabic: "إذن. اذهب."),
    ItemCard(english: "I really don't want to go by myself.", arabic: "أنا حقاً لا أريد الذهاب بمفردي."),
    ItemCard(english: "Well anyway, do you plan on going to school tomorrow?", arabic: "على أي حال، تخطط تروح المدرسة بكرة؟"),
    ItemCard(english: "No, I think I'm going to go to the movies.", arabic: "لا، أعتقد إني هروح السينما."),
    ItemCard(english: "Did you go to the meeting?", arabic: "هل ذهبت إلى الاجتماع؟"),
    ItemCard(english: "Did you make it to the meeting?", arabic: "هل استطعت الذهاب للاجتماع في الوقت المحدد؟"),
    ItemCard(english: "Sorry I can't make it.", arabic: "آسف لا أستطيع الحضور."),
    ItemCard(english: "You can make it.", arabic: "تستطيع النجاح في تجاوز هذا الأمر."),
    ItemCard(english: "I believe you can make it.", arabic: "أنا مؤمن أنك تستطيع تجاوز هذا الأمر."),
    ItemCard(english: "Did you make it to school today?", arabic: "هل استطعت الذهاب للمدرسة اليوم؟"),
    ItemCard(english: "I always do. Did you go to school today?", arabic: "أنا دائماً أفعل. هل ذهبت للمدرسة اليوم؟"),
    ItemCard(english: "No, I didn't.", arabic: "لا، لم أفعل."),
    ItemCard(english: "You should have, but have you seen any movies lately?", arabic: "كان يجب عليك، لكن هل شاهدت أي أفلام مؤخراً؟"),
    ItemCard(english: "That was an odd change of subject.", arabic: "ده كان تغيير غريب للموضوع."),
    ItemCard(english: "Maybe it was, but answer the question.", arabic: "يمكن كان كذلك، لكن أجب على السؤال."),
    ItemCard(english: "No not recently.", arabic: "لا، ليس مؤخراً."),
    ItemCard(english: "I want to go to see a movie this weekend.", arabic: "أريد الذهاب لمشاهدة فيلم عطلة الأسبوع دي."),
    ItemCard(english: "What's stopping you then?", arabic: "ما الذي يمنعك إذن؟"),
    ItemCard(english: "I don't want to go alone.", arabic: "لا أريد الذهاب بمفردي."),
    ItemCard(english: "So, will you be at school tomorrow?", arabic: "إذن، هتكون في المدرسة بكرة؟"),
    ItemCard(english: "No, I want to go the movies instead.", arabic: "لا، أريد الذهاب للسينما بدلاً من ذلك."),
    ItemCard(english: "You should have called me.", arabic: "كان يجب عليك أن تتصل بي."),
    ItemCard(english: "You should have apologized to your friend.", arabic: "كان يجب عليك أن تعتذر لصديقك."),
    ItemCard(english: "What's stopping you then? (مع الكلام غير الرسمي)", arabic: "ما الذي يمنعك إذن؟ (غير رسمي)"),
    ItemCard(english: "Why don't you go then? (مع الكلام الرسمي)", arabic: "لما لا تذهب إذن؟ (رسمي)"),
    ItemCard(english: "Did you even bother to go to school today?", arabic: "هل كلفت نفسك حتى بالذهاب للمدرسة اليوم؟"),
    ItemCard(english: "Is he bothering you?", arabic: "هل هو يزعجك؟"),
    ItemCard(english: "It was a stupid question, I didn't even bother to reply.", arabic: "كان سؤالاً غبياً، لم أكلف نفسي حتى بالرد."),
    ItemCard(english: "Has anyone even bothered to ask John about this opinion?", arabic: "هل كلف أي شخص نفسه بسؤال جون عن هذا الرأي؟"),
    ItemCard(english: "She was rude, I felt like leaving.", arabic: "هي كانت فظة، وأنا أردت المغادرة."),
    ItemCard(english: "I feel like Chinese food.", arabic: "أنا أريد طعام صيني."),
    ItemCard(english: "No, I didn't feel like it.", arabic: "لا، لم أرغب في ذلك."),
    ItemCard(english: "That's nice, have you been to the movies lately?", arabic: "ده لطيف، هل ذهبت للسينما مؤخراً؟"),
    ItemCard(english: "No, but that was a random change of subject.", arabic: "لا، لكن ده كان تغيير عشوائي للموضوع."),
    ItemCard(english: "It may have been random, but have you?", arabic: "يمكن كان عشوائياً، لكن هل فعلت؟"),
    ItemCard(english: "I haven't lately.", arabic: "لم أفعل مؤخراً."),
    ItemCard(english: "See a movie = Catch a movie.", arabic: "يشاهد فيلم = يشاهد فيلم."),
    ItemCard(english: "I would love to catch a movie this weekend.", arabic: "أود أن أشاهد فيلم عطلة الأسبوع دي."),
    ItemCard(english: "So then, why don't you just go?", arabic: "إذن، لما لا تذهب فقط؟"),
    ItemCard(english: "I don't want to see a movie by myself.", arabic: "لا أريد مشاهدة فيلم بمفردي."),
    ItemCard(english: "Okay, so are you going to school tomorrow?", arabic: "حسناً، إذن هتروح المدرسة بكرة؟"),
    ItemCard(english: "I think I might just go to the movies.", arabic: "أعتقد إني يمكن أروح السينما فقط."),

    // ===================== Ep8 =====================
    ItemCard(english: "Talk to = Talk with. There is no difference.", arabic: "يتحدث إلى = يتحدث مع. لا يوجد فرق."),
    ItemCard(english: "The waiter rushed us off the moment we paid the bill.", arabic: "النادل استعجلنا على المغادرة فور دفعنا الفاتورة."),
    ItemCard(english: "It was nice talking to you.", arabic: "كان من الجيد التحدث معك."),
    ItemCard(english: "Why are you trying to rush me off the phone?", arabic: "لماذا تحاول استعجالي على إنهاء المكالمة؟"),
    ItemCard(english: "I really have to go.", arabic: "أنا حقاً يجب أن أذهب."),
    ItemCard(english: "Why? I still want to talk to you?", arabic: "لماذا؟ ما زلت أريد التحدث معك؟"),
    ItemCard(english: "I have things to do.", arabic: "عندي أشياء لأفعلها."),
    ItemCard(english: "Like what?", arabic: "مثل ماذا؟"),
    ItemCard(english: "Don't be nosey.", arabic: "لا تكن متطفلاً."),
    ItemCard(english: "I'm not. I just want to know.", arabic: "أنا لا أتطفل. أنا فقط أريد أن أعرف."),
    ItemCard(english: "Well, it's really none of your business.", arabic: "حسناً، إنه حقاً ليس من شأنك."),
    ItemCard(english: "That's harsh.", arabic: "ده قاسي."),
    ItemCard(english: "I'm sorry, but I have to go.", arabic: "أنا آسف، لكن يجب أن أذهب."),
    ItemCard(english: "Fine.", arabic: "حسناً."),
    ItemCard(english: "I'll talk to later.", arabic: "سأتحدث معك لاحقاً."),
    ItemCard(english: "What's the rush?", arabic: "ما العجلة؟"),
    ItemCard(english: "I have to get off the phone now.", arabic: "يجب أن أنهي المكالمة الآن."),
    ItemCard(english: "I'm not ready to get off the phone with you.", arabic: "أنا لست مستعداً لإنهاء المكالمة معك."),
    ItemCard(english: "There other things I need to take care of.", arabic: "هناك أشياء أخرى أحتاج أن أعتني بها."),
    ItemCard(english: "What is it that you need to do?", arabic: "ما هو الشيء الذي تحتاج أن تفعله؟"),
    ItemCard(english: "Please don't be nosey.", arabic: "من فضلك لا تكن متطفلاً."),
    ItemCard(english: "I'm not being nosey, It's just a question.", arabic: "أنا لا أتطفل، إنه مجرد سؤال."),
    ItemCard(english: "You don't need to worry about that.", arabic: "لا تحتاج أن تقلق بشأن ذلك."),
    ItemCard(english: "That was mean to say.", arabic: "ده كان قصد قوله."),
    ItemCard(english: "I am very sorry, but I must go.", arabic: "أنا آسف جداً، لكن يجب أن أذهب."),
    ItemCard(english: "I guess.", arabic: "أعتقد."),
    ItemCard(english: "I have to go to the bathroom.", arabic: "يجب أن أذهب إلى الحمام."),
    ItemCard(english: "My god look at the time, I've got to go to work.", arabic: "يا إلهي انظر إلى الوقت، أنا مضطر للذهاب إلى العمل."),
    ItemCard(english: "I gotta go.", arabic: "يجب أن أذهب. (عامية)"),

    // ===================== Ep9 =====================
    ItemCard(english: "Invitation = Invitation card.", arabic: "دعوة = كارت دعوة."),
    ItemCard(english: "I guess my invitation got lost in the mail.", arabic: "أظن أن دعوتي قد ضاعت في البريد."),
    ItemCard(english: "May I see your invitation, please?", arabic: "هل تسمح أن أرى كارت الدعوة الخاص بك؟ من فضلك؟"),
    ItemCard(english: "Is that right? = Is that a fact?", arabic: "هل هذا حقيقي؟ = هل هذه حقيقة؟"),
    ItemCard(english: "John broke up with Mary. Is that right?", arabic: "جون انفصل عن ماري. هل هذا حقيقي؟"),
    ItemCard(english: "Did you know that Michael Jackson stole my song?", arabic: "هل تعلم أن مايكل جاكسون قد سرق أغنيتي؟"),
    ItemCard(english: "Wow, is that right? Bad bad Michael!", arabic: "واو، حقاً؟ سيء سيء يا مايكل!"),
    ItemCard(english: "Has anyone told you about Jessica's party coming up?", arabic: "هل أخبرك أحد عن حفلة جيسيكا القادمة؟"),
    ItemCard(english: "I was told about it already. I'm just waiting for my invitation.", arabic: "لقد أُخبرت عنه بالفعل. أنا فقط أنتظر دعوتي."),
    ItemCard(english: "Is that right? I already got my invitation from her earlier.", arabic: "هل هذا حقيقي؟ أنا بالفعل حصلت على دعوتي منها في وقت سابق."),
    ItemCard(english: "I believe that she will give me the invitation today.", arabic: "أعتقد أنها ستعطيني الدعوة اليوم."),
    ItemCard(english: "Are you even going to go?", arabic: "هل حتى ستذهب؟"),
    ItemCard(english: "Yeah, it sounds like it's going to be the best party of the year.", arabic: "أجل، يبدو أنها ستكون أفضل حفلة في السنة."),
    ItemCard(english: "Exactly, it seems like it's going to be loads of fun.", arabic: "بالضبط، يبدو أنها ستكون الكثير من المرح."),
    ItemCard(english: "When exactly does the party start?", arabic: "متى بالضبط تبدأ الحفلة؟"),
    ItemCard(english: "The invitation says it starts at 08:00 p.m.", arabic: "الدعوة تقول إنها تبدأ الساعة 8 مساءً."),
    ItemCard(english: "Has she given out a lot of invitations yet?", arabic: "هل وزعت الكثير من الدعوات بعد؟"),
    ItemCard(english: "I have no idea she hasn't given out many though.", arabic: "ليس لدي فكرة، لكنها لم توزع الكثير."),
    ItemCard(english: "I'm planning on going, but I really need her to give me my invitation.", arabic: "أنا أخطط للذهاب، لكني حقاً أحتاجها أن تعطيني دعوتي."),
    ItemCard(english: "Have you heard about Jessica's party on Saturday?", arabic: "هل سمعت عن حفلة جيسيكا يوم السبت؟"),
    ItemCard(english: "I've heard about it, but I'm still waiting for my invitation.", arabic: "سمعت عنها، لكني ما زلت أنتظر دعوتي."),
    ItemCard(english: "Really? I got mine from her this morning.", arabic: "حقاً؟ أنا حصلت على دعوتي منها هذا الصباح."),
    ItemCard(english: "I'm guessing that she's going to give me my invitation today or tomorrow.", arabic: "أخمن أنها ستعطيني دعوتي اليوم أو غداً."),
    ItemCard(english: "You're probably right, do you intend on going to the party?", arabic: "أنت على الأرجح محق، هل تنوي الذهاب للحفلة؟"),
    ItemCard(english: "I want to. I heard it's going to be really fun.", arabic: "أريد ذلك. سمعت أنها ستكون ممتعة حقاً."),
    ItemCard(english: "It's supposed to start at about eight.", arabic: "من المفترض أن تبدأ حوالي الثامنة."),
    ItemCard(english: "I know, It does sound pretty awesome.", arabic: "أعرف، يبدو رائعاً جداً."),
    ItemCard(english: "Well, when does the party start?", arabic: "حسناً، متى تبدأ الحفلة؟"),
    ItemCard(english: "How many invitations has she given out?", arabic: "كم دعوة وزعت؟"),
    ItemCard(english: "I don't know, but I don't think she gave out that many yet.", arabic: "لا أعرف، لكني لا أعتقد أنها وزعت الكثير بعد."),
    ItemCard(english: "I really want to go, so I hope that she gives me my invitation soon.", arabic: "أنا حقاً أريد الذهاب، لذا آمل أنها تعطيني دعوتي قريباً."),
    ItemCard(english: "I gave out samples and everyone said it was the bomb.", arabic: "وزعت عينات وكل الناس قالوا إنها الأفضل."),
    ItemCard(english: "My computer just gave out, I think I'll have to buy a new one.", arabic: "الكمبيوتر توقف عن العمل، أظن أني سأضطر لشراء جهاز جديد."),
    ItemCard(english: "People's hearts give out all the time, man.", arabic: "يحدث كثيراً أن تتوقف قلوب الناس عن العمل، يا راجل."),
    ItemCard(english: "Later = Later on.", arabic: "لاحقاً = لاحقاً."),
    ItemCard(english: "I am planning a trip to Europe.", arabic: "أنا أخطط رحلة لأوروبا."),
    ItemCard(english: "I am planning to go to Europe.", arabic: "أنا أخطط أن أذهب لأوروبا."),
    ItemCard(english: "I am planning on going to Europe.", arabic: "أنا أخطط للذهاب إلى أوروبا."),
    ItemCard(english: "I intend to go Europe.", arabic: "أنوي أن أذهب لأوروبا."),
    ItemCard(english: "I intend on going to Europe.", arabic: "أنوي الذهاب إلى أوروبا."),
    ItemCard(english: "Hey, did you hear about Jessica's party this weekend?", arabic: "هاي، هل سمعت عن حفلة جيسيكا عطلة الأسبوع دي؟"),
    ItemCard(english: "Yeah, but I'm still waiting for my invitation.", arabic: "أجل، لكني ما زلت أنتظر دعوتي."),
    ItemCard(english: "Oh really? She gave me mine earlier today.", arabic: "أوه حقاً؟ هي أعطتني دعوتي في وقت سابق اليوم."),
    ItemCard(english: "Well, she'll probably just give me my invitation later on today.", arabic: "حسناً، على الأرجح ستعطيني دعوتي لاحقاً اليوم."),
    ItemCard(english: "Yeah, so are you planning on going?", arabic: "أجل، هل تخطط للذهاب؟"),
    ItemCard(english: "I think so. It sounds like it's going to be a lot of fun.", arabic: "أعتقد ذلك. يبدو أنها ستكون الكثير من المرح."),
    ItemCard(english: "It really does. I can't wait.", arabic: "إنها حقاً كذلك. لا أستطيع الانتظار."),
    ItemCard(english: "It really does = It really does sound like.", arabic: "إنها حقاً كذلك = إنها حقاً تبدو كذلك."),
    ItemCard(english: "You know what holiday is coming up, don't you?", arabic: "أنت تعرف أي إجازة على وشك أن تأتي، أليس كذلك؟"),
    ItemCard(english: "What time does the party start?", arabic: "في أي وقت تبدأ الحفلة؟"),
    ItemCard(english: "Oh, well, how many people has she given invitation to so far?", arabic: "أوه، حسناً، كم شخصاً أعطته دعوة حتى الآن؟"),
    ItemCard(english: "Mark come up to me and whispered in my ear.", arabic: "مارك اقترب مني وهمس في أذني."),
    ItemCard(english: "On the subway, a man come up to me to start a conversation.", arabic: "في المترو، اقترب مني رجل ليبدأ محادثة."),
    ItemCard(english: "I can come up with good excuse.", arabic: "يمكنني أن آتي بعذر جيد."),
    ItemCard(english: "I'm not sure, but I don't think she's given out that many.", arabic: "لست متأكداً، لكني لا أعتقد أنها وزعت الكثير."),
    ItemCard(english: "Well, hopefully she'll give me my invitation later on today.", arabic: "حسناً، على أمل أنها ستعطيني دعوتي لاحقاً اليوم."),

    // ===================== Ep10 =====================
    ItemCard(english: "What do you think you're doing?", arabic: "ماذا تظن نفسك فاعلاً؟"),
    ItemCard(english: "\"What do you think you're doing?\" Is not a real question. It's just a way to show that you're surprised or displeased with someone's action.", arabic: "\"ماذا تظن نفسك فاعلاً؟\" ليس سؤالاً حقيقياً. إنه مجرد طريقة لإظهار أنك متفاجئ أو غير راضٍ عن تصرف شخص ما."),
    ItemCard(english: "When people are angry, they usually say \"What the heck do you think you're doing?\"", arabic: "عندما يغضب الناس، عادةً يقولون \"ماذا بحق الجحيم تظن نفسك فاعلاً؟\""),
    ItemCard(english: "The word heck, is the polite way of saying \"hell\". Don't say hell, it's not polite.", arabic: "كلمة heck هي الطريقة المهذبة لقول \"hell\". لا تقل hell، فهي غير مهذبة."),
    ItemCard(english: "I can't study at home, because my family talks so loudly.", arabic: "لا أستطيع الدراسة في المنزل، لأن أفراد عائلتي يتحدثون بصوت عالٍ."),
    ItemCard(english: "The word \"family\" is a collective noun.", arabic: "كلمة \"family\" هي اسم جماعي."),
    ItemCard(english: "Collective nouns are names of collections of people or things.", arabic: "الأسماء الجماعية هي أسماء مجموعات من الناس أو الأشياء."),
    ItemCard(english: "Team = a collection of players.", arabic: "فريق = مجموعة من اللاعبين."),
    ItemCard(english: "Staff = a collection of people who work in the same place.", arabic: "طاقم العمل = مجموعة من الأشخاص الذين يعملون في نفس المكان."),
    ItemCard(english: "Flock = a collection of birds.", arabic: "سرب = مجموعة من الطيور."),
    ItemCard(english: "Collective nouns can be thought of as single or plural nouns.", arabic: "يمكن اعتبار الأسماء الجماعية أسماء مفردة أو جمع."),
    ItemCard(english: "Sometimes we can use collective nouns as single. My family talks.", arabic: "أحياناً نستخدم الأسماء الجماعية كمفرد. عائلتي تتحدث."),
    ItemCard(english: "We added (s) because we treated the word \"family\" as a single noun.", arabic: "أضفنا (s) لأننا عاملنا كلمة \"family\" كاسم مفرد."),
    ItemCard(english: "And sometimes we will use it as plural. Saw a flock of sheep.", arabic: "وأحياناً نستخدمها كجمع. رأيت سرباً من الخرفان."),
    ItemCard(english: "The verb that follows will not need an extra (s).", arabic: "الفعل الذي يليها لن يحتاج (s) إضافية."),
    ItemCard(english: "I'll give it a shot. That's an idiom. Meaning: to give something a shot is to try to do it.", arabic: "سأجربها. هذا تعبير اصطلاحي. المعنى: أن تجرب شيئاً هو أن تحاول فعله."),
    ItemCard(english: "Dude is American English slang for \"guy\" or \"man\" or in other countries like Australia or England \"mate\".", arabic: "Dude هي عامية أمريكية تعني \"guy\" أو \"man\" أو في دول أخرى مثل أستراليا أو إنجلترا \"mate\"."),
    ItemCard(english: "They tend to close late. Tend to do something means: to frequently do it. You can think of it as saying \"usually\".", arabic: "هم يميلون إلى الإغلاق متأخراً. Tend to do something تعني: أن تفعلها بشكل متكرر. يمكنك اعتبارها بمعنى \"عادةً\"."),
    ItemCard(english: "Hey, what do you think you're doing?", arabic: "هاي، ماذا تظن نفسك فاعلاً؟"),
    ItemCard(english: "I can't study at home, because my family talks so loudly.", arabic: "لا أستطيع الدراسة في المنزل، لأن أفراد عائلتي يتحدثون بصوت عالٍ."),
    ItemCard(english: "Well, study at the library then.", arabic: "حسناً، ادرس في المكتبة إذن."),
    ItemCard(english: "Can you really focus in there?", arabic: "هل يمكنك حقاً التركيز هناك؟"),
    ItemCard(english: "Yes, it's always really quiet.", arabic: "نعم، إنها حقاً هادئة دائماً."),
    ItemCard(english: "I'll give it a shot today.", arabic: "سوف أقوم بتجربتها اليوم."),
    ItemCard(english: "When you do, make sure you get a good seat.", arabic: "عند القيام بذلك، تأكد من حصولك على مقعد جيد."),
    ItemCard(english: "Why? Are there not enough seats for everyone?", arabic: "لماذا؟ ألا توجد مقاعد كافية للجميع؟"),
    ItemCard(english: "It depends on when you go.", arabic: "ذلك يعتمد على وقت ذهابك."),
    ItemCard(english: "I'm going at 1:00 a.m.", arabic: "سوف أذهب في الواحدة صباحاً."),
    ItemCard(english: "Dude, it's not even open that late.", arabic: "يا صاحبي، لن تكون مفتوحة في ذلك الوقت المتأخر."),
    ItemCard(english: "But that's the best time for me.", arabic: "ولكن هذا هو أفضل وقت بالنسبة لي."),
    ItemCard(english: "You can always try a cafe. They tend to close late or sometimes not at all.", arabic: "يمكنك دائماً تجربة مقهى. ما يفضلون الإغلاق في وقت متأخر أو لا يغلقون على الإطلاق."),
    ItemCard(english: "Alright. Good one.", arabic: "حسناً. فكرة جيدة."),

    // ===================== Ep11 =====================
    ItemCard(english: "\"Can you please shut up?\" The word \"shut up\" isn't usually polite. He was angry. That's why he used the word \"shut up\".", arabic: "\"من فضلك هل يمكنك أن تغلق فمك؟\" كلمة \"shut up\" عادةً ليست مهذبة. كان غاضباً. لهذا استخدم كلمة \"shut up\"."),
    ItemCard(english: "He could have said other things and would have been much nicer.", arabic: "كان يمكنه قول أشياء أخرى وكان سيكون ألطف بكثير."),
    ItemCard(english: "Could you please speak a bit quieter?", arabic: "ممكن تتحدث بصوت أهدأ قليلاً؟"),
    ItemCard(english: "I'm sorry, would you mind keeping it down?", arabic: "أنا آسف، هل تمانع في خفض صوتك؟"),
    ItemCard(english: "\"Maybe if you ask nicely\" It means you admit that what you're doing is not ideal but you aren't happy with the method of bringing your attention to it.", arabic: "\"ربما إذا سألت بلطف\" تعني أنك تعترف أن ما تفعله ليس مثالياً لكنك لست سعيداً بالطريقة التي لُفت بها انتباهك إلى ذلك."),
    ItemCard(english: "It's like saying \"Ok, I know my behavior isn't the best, but I don't appreciate the way you're talking to me\".", arabic: "إنها مثل قول \"حسناً، أنا أعرف أن سلوكي ليس الأفضل، لكني لا أقدّر الطريقة التي تتحدث بها معي\"."),
    ItemCard(english: "\"I have no interest in splitting hairs\" That's an idiom.", arabic: "\"ليس لدي أي رغبة في الدخول بجدال غير مجدي\" هذا تعبير اصطلاحي."),
    ItemCard(english: "If we say that someone is splitting hairs, what we actually mean is they are trying to argue about very small and unimportant details.", arabic: "إذا قلنا أن شخصاً ما يجادل في تفاهات، ما نعنيه فعلاً هو أنه يحاول الجدال حول تفاصيل صغيرة وغير مهمة."),
    ItemCard(english: "As you can see, arguing about that is a waste of time. It's splitting hairs.", arabic: "كما ترى، الجدال حول ذلك مضيعة للوقت. إنه جدال في تفاهات."),
    ItemCard(english: "\"I'm sorry that your parents didn't teach you how to be nice\" This is a very annoying statement.", arabic: "\"أنا آسف لأن والديك لم يعلماك كيف تكون لطيفاً\" هذه جملة مزعجة جداً."),
    ItemCard(english: "It's like he's saying. \"Well, it seems you are fixating on me having to say sorry. Ok, I will give you the sorry that you're looking for but you're not gonna like it\".", arabic: "يبدو وكأنه يقول: \"حسناً، يبدو أنك تركز على أنه يجب عليّ أن أقول آسف. حسناً، سأعطيك الاعتذار الذي تبحث عنه لكنك لن تحبه\"."),
    ItemCard(english: "Can you please shut up?", arabic: "من فضلك هل يمكنك أن تغلق فمك؟"),
    ItemCard(english: "This is a library, so you have to shut up.", arabic: "هذه مكتبة، لذا عليك أن تصمت."),
    ItemCard(english: "Maybe if you ask nicely, I will!", arabic: "ربما إذا سألت بلطف، سأفعل!"),
    ItemCard(english: "Well, I have no interest in splitting hairs. What you're doing is wrong.", arabic: "حسناً، ليس لدي رغبة في الدخول بجدال غير مجدي. ما تفعله خطأ."),
    ItemCard(english: "I didn't know laughing was a crime.", arabic: "لم أكن أعرف أن الضحك كان جريمة."),
    ItemCard(english: "It's a crime when you do it in the library.", arabic: "إنها جريمة عندما تفعل ذلك في المكتبة."),
    ItemCard(english: "You're just jealous, because I'm having a good time, and you're not.", arabic: "أنت فقط تشعر بالغيرة، لأنني أمرح، وأنت لا تفعل."),
    ItemCard(english: "Nope, that's not it. Try again.", arabic: "كلا، ليست هذه. حاول مرة أخرى."),
    ItemCard(english: "I'll shut up if you say you're sorry.", arabic: "سأصمت إذا قلت إنك آسف."),
    ItemCard(english: "Sorry for what? If anything, you should say sorry.", arabic: "آسف على ماذا؟ إذا كان لا بد من الاعتذار، فأنت من يجب عليه أن يعتذر."),
    ItemCard(english: "Okay, fine. I'm sorry that your parents didn't teach you how to be nice.", arabic: "حسناً. أنا آسف لأن والديك لم يعلماك كيف تكون لطيفاً."),
    ItemCard(english: "Alright, that's it. I'm getting a librarian.", arabic: "هذا يكفي. سوف أحضر أمين مكتبة."),
    ItemCard(english: "Ohh, a librarian. Scary!", arabic: "أوه، أمين مكتبة! مخيف!"),
    ItemCard(english: "I don't know if I have to.", arabic: "لا أعرف إذا كان عليّ ذلك."),

    // ===================== Ep12 =====================
    ItemCard(english: "A: Hey, Steve. Do you know where I can look for used cars? B: To buy? A: What else?", arabic: "أ: هاي ستيف. تعرف وين أقدر أبحث عن سيارات مستعملة؟ ب: لتشتري؟ أ: وإلا لماذا؟"),
    ItemCard(english: "\"What else?\" This way, you express that you're surprised by the question. It's like saying \"Isn't it clear already? Why do you have to ask?\".", arabic: "\"وإلا لماذا؟\" بهذه الطريقة، تعبر عن أنك متفاجئ من السؤال. إنها مثل قول \"أليست واضحة بالفعل؟ لماذا تسأل؟\"."),
    ItemCard(english: "We could use another word in this situation, the word is \"duh\". Duh means \"of course\" - \"what else\" - \"same thing\".", arabic: "يمكننا استخدام كلمة أخرى في هذه الحالة، وهي \"duh\". duh تعني \"بالطبع\" - \"وإلا لماذا\" - \"نفس الشيء\"."),
    ItemCard(english: "\"There is a dealership that sells used cars on Victoria street\" The word dealership comes from the word deal.", arabic: "\"هناك وكالة لبيع السيارات المستعملة في شارع فيكتوريا\" كلمة dealership تأتي من كلمة deal."),
    ItemCard(english: "When you go buy a car, you're making a deal.", arabic: "عندما تذهب لشراء سيارة، فأنت تعقد صفقة."),
    ItemCard(english: "The person who sells you the car, we call him \"a dealer\".", arabic: "الشخص الذي يبيعك السيارة، نسميه \"dealer\"."),
    ItemCard(english: "A dealer is a person who sells goods.", arabic: "التاجر هو شخص يبيع البضائع."),
    ItemCard(english: "A dealership is the company that has the permission to sell you these cars.", arabic: "الوكالة هي الشركة التي لديها الإذن لبيع هذه السيارات لك."),
    ItemCard(english: "\"I'm down. Can you go with me?\" I'm down is a slang term that we use to show agreement.", arabic: "\"أنا موافق. ممكن تروح معي؟\" I'm down هي كلمة عامية نستخدمها لإظهار الموافقة."),
    ItemCard(english: "We can use both \"up\" or \"down\" to show agreement. For example, I can say \"I'm up for it\".", arabic: "يمكننا استخدام \"up\" أو \"down\" لإظهار الموافقة. مثلاً، يمكنني قول \"I'm up for it\"."),
    ItemCard(english: "\"I'm up for it\" means \"count me in\" - \"include me\" - \"I'm OK with it\".", arabic: "\"I'm up for it\" تعني \"احسبني معكم\" - \"أشركني\" - \"أنا موافق\"."),
    ItemCard(english: "We can also say \"I'm down with that\". I'm down with that means \"I like that\" - \"I'm OK with that\" - \"I agree to that\".", arabic: "يمكننا أيضاً قول \"I'm down with that\". تعني \"أحب ذلك\" - \"أنا موافق على ذلك\" - \"أوافق على ذلك\"."),
    ItemCard(english: "\"Shoot me a text\" That's a slang term and a cool way of saying \"Send me a text\".", arabic: "\"Shoot me a text\" هذه كلمة عامية وطريقة رائعة لقول \"ابعتلي رسالة نصية\"."),
    ItemCard(english: "\"You owe me\" Here means \"I am doing you a favor\" so you owe me a favor.", arabic: "\"You owe me\" هنا تعني \"أنا أقدم لك خدمة\" لذا أنت مدين لي بخدمة."),
    ItemCard(english: "Hey, Steve. Do you know where I can look for used cars?", arabic: "هاي ستيف. تعرف وين أقدر أبحث عن سيارات مستعملة؟"),
    ItemCard(english: "To buy?", arabic: "لتشتري؟"),
    ItemCard(english: "What else?", arabic: "وإلا لماذا؟"),
    ItemCard(english: "Hmm, you could always check online. My friend bought a car from Craigslist.", arabic: "مم، يمكنك دائماً البحث عبر الإنترنت. صديقي اشترى سيارة من كريغسليست."),
    ItemCard(english: "Yeah, I was thinking about that. Do you know any other way though?", arabic: "أها، كنت أفكر بهذا. هل تعرف أي طرق أخرى؟"),
    ItemCard(english: "There is a dealership that sells used cars on Victoria street.", arabic: "هناك وكالة لبيع السيارات المستعملة في شارع فيكتوريا."),
    ItemCard(english: "Where in Victoria street? I have never seen one.", arabic: "أين تحديداً في شارع فيكتوريا؟ لم أرَ أياً منها."),
    ItemCard(english: "It's on the corner of Abby and Victoria.", arabic: "إنها في زاوية آبي وفيكتوريا."),
    ItemCard(english: "Oh, by the Burger King?", arabic: "أها، بالقرب من برجر كينج؟"),
    ItemCard(english: "Yeah. That's the one. They have a pretty good selection. You should check it out.", arabic: "بالفعل هذه هي. لديهم تشكيلة جيدة جداً. عليك تفقدها."),
    ItemCard(english: "I'm down. Can you go with me?", arabic: "يناسبني تماماً. هل تأتي معي؟"),
    ItemCard(english: "Sure, I am free tomorrow and Thursday. Shoot me a text.", arabic: "بالتأكيد، أنا متاح غداً ويوم الخميس. رسلني."),
    ItemCard(english: "Will do, man. Thanks.", arabic: "سأفعل، شكراً يا رجل."),
    ItemCard(english: "Sure thing, bro. You owe me, though.", arabic: "بالتأكيد يا صاحبي. تذكر أنت مدين لي بواحدة."),
    ItemCard(english: "Hahaha, but you'll never collect.", arabic: "هاهاها، لكن لن تسترده أبداً."),
    ItemCard(english: "True.", arabic: "حقيقي."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Lv2 Summary 2 - الجمل (Ep6 → Ep12)",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


