    LearningCard(primaryText: "Bear in mind", secondaryText: "ضع في اعتبارك"),
    LearningCard(primaryText: "Ideal", secondaryText: "مثالي"),
    LearningCard(primaryText: "Patient", secondaryText: "صبور"),
    LearningCard(primaryText: "Perfectionist", secondaryText: "مثالي / كمالي"),
    LearningCard(primaryText: "Bullsh", secondaryText: "هراء (اختصار)"),
    LearningCard(primaryText: "Off the top", secondaryText: "من رأس مباشرة"),
    LearningCard(primaryText: "Main", secondaryText: "رئيسي"),
    LearningCard(primaryText: "Tolerate", secondaryText: "يتحمل / يتحمل"),
    LearningCard(primaryText: "Sloppy", secondaryText: "مهمل / غير منظم"),
    LearningCard(primaryText: "Tough", secondaryText: "قوي / صعب"),
    LearningCard(primaryText: "Lead", secondaryText: "يقود / قيادة"),
    LearningCard(primaryText: "Homework", secondaryText: "واجب"),
    LearningCard(primaryText: "Internet", secondaryText: "إنترنت"),
    LearningCard(primaryText: "Expect", secondaryText: "يتوقع"),
    LearningCard(primaryText: "Contacted", secondaryText: "يتم الاتصال به"),
    LearningCard(primaryText: "HR representative", secondaryText: "ممثل الموارد البشرية"),
    LearningCard(primaryText: "Within", secondaryText: "خلال / في غضون"),
    LearningCard(primaryText: "Two weeks", secondaryText: "أسبوعان"),
    LearningCard(primaryText: "Thanks again", secondaryText: "شكراً مجدداً"),
    LearningCard(primaryText: "Having me", secondaryText: "استضافتي"),
    LearningCard(primaryText: "Good day", secondaryText: "يوم سعيد"),
    LearningCard(primaryText: "Sir", secondaryText: "سيدي"),
  ];

  @override
  Widget build(BuildContext context) {
    return LearningCardsScreen(
      categoryTitle: "Lv2 Summary 3 - الكلمات (Ep13 → Ep16)",
      cards: Cards,
    );
  }
}

class ConversationLv2Summary3SentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===================== Ep13 =====================
    ItemCard(english: "A: What's up man? B: Nothing much.", arabic: "أ: كيف حالك يا رجل؟ ب: لا جديد."),
    ItemCard(english: "When you say nothing much in response to someone asking how you're doing. It means \"Nothing important\".", arabic: "عندما تقول nothing much رداً على سؤال كيف حالك، فهي تعني \"لا شيء مهم\"."),
    ItemCard(english: "B: How are you doing? A: Better than I deserve.", arabic: "ب: كيف حالك؟ أ: أفضل مما أستحق."),
    ItemCard(english: "When you are happy with how everything is going in your life, you can use that \"Better than I deserve\" or \"Can't complain\".", arabic: "عندما تكون سعيداً بسير كل شيء في حياتك، يمكنك استخدام \"أفضل مما أستحق\" أو \"لا أستطيع الشكوى\"."),
    ItemCard(english: "Can't complain means you're satisfied with how everything is going in your life.", arabic: "Can't complain تعني أنك راضٍ عن سير كل شيء في حياتك."),
    ItemCard(english: "\"To what do I owe the pleasure?\" This is a good way to ask why someone is calling.", arabic: "\"لماذا سررت باتصالك؟\" هذه طريقة جيدة للسؤال عن سبب اتصال شخص ما."),
    ItemCard(english: "To what do I owe the pleasure is used when you want to ask why someone is contacting you.", arabic: "To what do I owe the pleasure تُستخدم عندما تريد السؤال عن سبب تواصل شخص معك."),
    ItemCard(english: "If we say \"Why are you calling me?\" That could be very rude.", arabic: "إذا قلنا \"لماذا تتصل بي؟\" فقد يكون ذلك وقحاً جداً."),
    ItemCard(english: "It's like you're saying \"I don't want to hear from you. Stop calling me\".", arabic: "يبدو وكأنك تقول \"لا أريد أن أسمع منك. توقف عن الاتصال بي\"."),
    ItemCard(english: "\"I was wondering if you could hook me up at the place you work\" Hook me up is a phrasal verb. It has several meanings.", arabic: "\"كنت أتساءل إن كان بإمكانك أن تتوسط لي للحصول على وظيفة في مكان عملك\" Hook me up هو فعل مركب. له عدة معانٍ."),
    ItemCard(english: "In American English when you say hook someone up with something. It means that you will give them something through your connection. Your connection of people, or contacts.", arabic: "في الإنجليزية الأمريكية عندما تقول hook someone up with something، فهي تعني أنك ستعطيهم شيئاً من خلال معارفك. معارفك من الناس أو جهات الاتصال."),
    ItemCard(english: "\"You're the bomb!\" When we say that something or someone is the bomb. That's slang for saying \"you're cool\" - \"You're awesome\" - \"you're great\".", arabic: "\"أنت رائع!\" عندما نقول أن شيئاً أو شخصاً ما هو the bomb. هذه عامية لقول \"أنت رائع\" - \"أنت مذهل\" - \"أنت عظيم\"."),
    ItemCard(english: "\"I'm learning to keep my chin up.\" To keep your chin up is an idiom that means \"that you're trying to remain happy, cheerful and to keep having hope especially in difficult times\".", arabic: "\"أنا أتعلم أن أتفاءل.\" To keep your chin up هو تعبير اصطلاحي يعني \"أنك تحاول أن تبقى سعيداً ومبتهجاً وتحافظ على الأمل خاصة في الأوقات الصعبة\"."),
    ItemCard(english: "Hey Mark. What's up man?", arabic: "مرحباً مارك. كيف حالك يا رجل؟"),
    ItemCard(english: "Hi, Jack. Nothing much. How are you doing?", arabic: "أهلاً جاك. لا جديد. كيف حالك؟"),
    ItemCard(english: "Better than I deserve. To what do I owe the pleasure?", arabic: "أفضل مما أستحق. لماذا سررت باتصالك؟"),
    ItemCard(english: "I'm looking for a job. I was hoping you could help me.", arabic: "أبحث عن وظيفة. كنت أتمنى أن تستطيع مساعدتي."),
    ItemCard(english: "Sure, how can I help?", arabic: "بالتأكيد، كيف يمكنني مساعدتك؟"),
    ItemCard(english: "Well, I was wondering if you could hook me up at the place you work.", arabic: "حسناً، كنت أتساءل إن كان بإمكانك أن تتوسط لي للحصول على وظيفة في مكان عملك."),
    ItemCard(english: "No problem. I don't know if they're hiring, but I'll find out.", arabic: "لا مشكلة. لا أعرف إذا كانوا يوظفون، لكني سأكتشف ذلك."),
    ItemCard(english: "Thanks man, you're the bomb!", arabic: "شكراً يا رجل، أنت رائع!"),
    ItemCard(english: "What kind of job are you interested in doing?", arabic: "أي نوع من الوظائف أنت مهتم بالقيام به؟"),
    ItemCard(english: "Anything you think that I can do will be fine.", arabic: "أي شيء تعتقد أني أستطيع فعله سيكون جيداً."),
    ItemCard(english: "Can't you be a little more specific?", arabic: "هل يمكنك أن تكون أكثر تحديداً؟"),
    ItemCard(english: "I wish I could, man but honestly any thing would be fine.", arabic: "أتمنى لو كنت أستطيع، صدقني يا رجل أي شيء سيكون جيداً بالنسبة لي."),
    ItemCard(english: "That bad, ha?", arabic: "ألهذه الدرجة، ها؟"),
    ItemCard(english: "Well, I'm learning to keep my chin up.", arabic: "حسناً، ما زلت أتمسك بالأمل."),
    ItemCard(english: "Good man. I'll talk to my boss in the morning and get back to you.", arabic: "جيد. سأتحدث إلى رئيسي بالعمل صباحاً ثم سأخبرك."),
    ItemCard(english: "Thanks, man. A friend in need is a friend indeed.", arabic: "شكراً يا رجل. الصديق وقت الضيق."),
    ItemCard(english: "Of course. Anything else you need me to do?", arabic: "بالتأكيد. هل هناك شيء آخر أستطيع مساعدتك به؟"),
    ItemCard(english: "No. I'm waiting to hear from you.", arabic: "لا. أنا في انتظار ردك."),
    ItemCard(english: "Alright, take care.", arabic: "حسناً، اعتن بنفسك."),
    ItemCard(english: "Yeah, you too.", arabic: "أجل، وأنت أيضاً."),

    // ===================== Ep14 =====================
    ItemCard(english: "\"Yo Mark, What up man?\" Yo is slang and we use it for 3 main purposes.", arabic: "\"يو مارك، إيه الأخبار يا راجل؟\" Yo هي عامية ونستخدمها لثلاثة أغراض رئيسية."),
    ItemCard(english: "First usage of Yo is to greet someone. It's like saying \"hello\".", arabic: "الاستخدام الأول لـ Yo هو تحية شخص ما. إنها مثل قول \"hello\"."),
    ItemCard(english: "Second usage of Yo is to attract someone's attention.", arabic: "الاستخدام الثاني لـ Yo هو جذب انتباه شخص ما."),
    ItemCard(english: "You want someone to pay attention to you. Or perhaps someone is not looking at you and you want them to turn their heads to your direction.", arabic: "تريد أن ينتبه شخص ما إليك. أو ربما شخص لا ينظر إليك وتريد أن يستدير في اتجاهك."),
    ItemCard(english: "Yo in this usage, it is equal to saying \"hey\".", arabic: "Yo في هذا الاستخدام تعادل قول \"hey\"."),
    ItemCard(english: "Third usage of Yo is to express excitement. It's like saying \"Wow\".", arabic: "الاستخدام الثالث لـ Yo هو التعبير عن الحماس. إنها مثل قول \"واو\"."),
    ItemCard(english: "\"I was about to call you? What's the word?\"", arabic: "\"كنت على وشك الاتصال بك؟ أخبارك يا صديقي.\""),
    ItemCard(english: "What's the word is slang and we use it to ask someone how they are doing. It's like saying \"how are you\", \"howdy\", \"how is it going\", \"what's up\", \"what's happening\", \"how are things\" and all of that.", arabic: "What's the word هي عامية ونستخدمها للسؤال عن حال شخص ما. إنها مثل قول \"كيف حالك\"، \"howdy\"، \"كيف تسير الأمور\"، \"what's up\"، \"ماذا يحدث\"، \"كيف الأمور\" وكل ذلك."),
    ItemCard(english: "A: All good. Got some good news for you by the way. B: Brilliant. Spill it, Jay.", arabic: "أ: كل شيء بخير. بالمناسبة لدي أخبار جيدة لك. ب: رائع. قولها يا جاي."),
    ItemCard(english: "Brilliant is a word that we can use to express happiness or satisfaction. Use it the same way you use, awesome, great, amazing.", arabic: "Brilliant كلمة يمكننا استخدامها للتعبير عن السعادة أو الرضا. استخدمها بنفس طريقة awesome، great، amazing."),
    ItemCard(english: "Spill it is slang for \"talk\" - \"say it\".", arabic: "Spill it هي عامية تعني \"تحدث\" - \"قلها\"."),
    ItemCard(english: "We can also use another word similar to this and say \"spit it out\".", arabic: "يمكننا أيضاً استخدام كلمة أخرى مشابهة ونقول \"spit it out\"."),
    ItemCard(english: "Of course we don't want the person to eject saliva out of their mouths, but we want them to hurry up and talk.", arabic: "بالطبع لا نريد أن يخرج الشخص اللعاب من فمه، لكننا نريده أن يسرع ويتحدث."),
    ItemCard(english: "Jay is a nickname for Jack.", arabic: "Jay هو لقب لـ Jack."),
    ItemCard(english: "\"Thanks a lot, bud. Did he say he has an open position?\"", arabic: "\"شكراً جزيلاً يا صاحبي. هل قال أن لديه وظيفة شاغرة؟\""),
    ItemCard(english: "The word bud is short for buddy. Buddy means \"close friend\".", arabic: "كلمة bud هي اختصار لـ buddy. Buddy تعني \"صديق مقرب\"."),
    ItemCard(english: "An open position is a vacant job.", arabic: "الوظيفة الشاغرة هي وظيفة خالية."),
    ItemCard(english: "A vacant job means a job that nobody is filling at the moment, so it's available for someone to come and take it.", arabic: "الوظيفة الشاغرة تعني وظيفة لا يشغلها أحد في الوقت الحالي، لذا فهي متاحة لشخص ما ليأتي ويأخذها."),
    ItemCard(english: "\"No, he didn't mention any vacancy at the moment.\" The word vacancy is the noun from vacant.", arabic: "\"لا، لم يذكر أي شاغر في الوقت الحالي.\" كلمة vacancy هي الاسم من vacant."),
    ItemCard(english: "Yo Mark, What up man?", arabic: "يو مارك، أخبارك يا صديقي."),
    ItemCard(english: "Hey Jack, I was about to call you? What's the word?", arabic: "أهلاً جاك، كنت على وشك الاتصال بك؟ أخبارك يا صديقي."),
    ItemCard(english: "All good. Got some good news for you by the way.", arabic: "بخير. بالمناسبة لدي أخبار جيدة لك."),
    ItemCard(english: "Brilliant. Spill it, Jay.", arabic: "رائع. قولها يا جاي."),
    ItemCard(english: "Okay, I talked to my boss. I will text you his phone number.", arabic: "حسناً، لقد تكلمت مع رئيسي بالعمل. سوف أرسل لك رقم هاتفه."),
    ItemCard(english: "Thanks a lot, bud. Did he say he has an open position?", arabic: "شكراً جزيلاً يا صاحبي. هل قال أن لديه وظيفة شاغرة؟"),
    ItemCard(english: "No, he didn't mention any vacancy at the moment, but he said he would talk to you.", arabic: "لا، لم يذكر شيئاً عن وظائف شاغرة حالياً، ولكنه قال أنه سيتحدث إليك."),
    ItemCard(english: "That's great! Hey, thanks again man.", arabic: "هذا رائع! شكراً لك مجدداً يا رجل."),
    ItemCard(english: "Sure. You know, you should also go online to look for work.", arabic: "بكل تأكيد، أتعلم، يجب عليك البحث عبر الإنترنت عن وظيفة."),
    ItemCard(english: "Online? Where?", arabic: "عبر الإنترنت؟ أين؟"),
    ItemCard(english: "There are many job search websites.", arabic: "هناك العديد من المواقع الإلكترونية للبحث عن وظائف."),
    ItemCard(english: "Cool. Do you know any by name?", arabic: "رائع. هل تعرف أي أسماء منها؟"),
    ItemCard(english: "Just Google \"Jobs in Cairo\" and you'll find some.", arabic: "فقط استخدم محرك البحث جوجل ابحث عن \"وظائف بالقاهرة\" وستجد البعض منها."),
    ItemCard(english: "Okay, I'll try that when I get home.", arabic: "حسناً. سأجرب حين أصل البيت."),
    ItemCard(english: "You can do it on your smartphone, you know.", arabic: "أتدري، يمكنك البحث من خلال هاتفك الذكي."),
    ItemCard(english: "I know, but I think it's better at home, thanks again.", arabic: "أعلم هذا، لكني أعتقد أنه من الأفضل البحث بالمنزل، شكراً مجدداً."),

    // ===================== Ep15 =====================
    ItemCard(english: "\"Man, Am I excited?\" That wasn't a real question.", arabic: "\"يا راجل، كم أنا متحمس!\" لم يكن سؤالاً حقيقياً."),
    ItemCard(english: "He is not actually saying \"Do you think I'm excited?\" or \"Do I look like I'm excited?\"", arabic: "هو لا يقول فعلاً \"هل تعتقد أني متحمس؟\" أو \"هل أبدو متحمساً؟\""),
    ItemCard(english: "No, he wasn't asking at all. So why did he say \"am I excited?\" instead of \"I am excited\"?", arabic: "لا، لم يكن يسأل على الإطلاق. فلماذا قال \"am I excited?\" بدلاً من \"I am excited\"؟"),
    ItemCard(english: "He could have said that, but it's more common to express excitement in the form of a question.", arabic: "كان يمكنه قول ذلك، لكن من الشائع أكثر التعبير عن الحماس في صيغة سؤال."),
    ItemCard(english: "Example: Wow, it's so beautiful. > Wow, is it beautiful?", arabic: "مثال: واو، إنها جميلة جداً. > واو، هل هي جميلة؟"),
    ItemCard(english: "My god, he is so annoying. > My god, is he annoying?", arabic: "يا إلهي، إنه مزعج جداً. > يا إلهي، هل هو مزعج؟"),
    ItemCard(english: "\"It's an internship for a tech company.\"", arabic: "\"إنها فترة تدريب لشركة تقنية.\""),
    ItemCard(english: "An internship is when you get a position in a company as a student or a trainee. You work there sometimes without getting paid because you want to learn and gain more experience.", arabic: "فترة التدريب هي عندما تحصل على منصب في شركة كطالب أو متدرب. تعمل هناك أحياناً بدون أجر لأنك تريد التعلم واكتساب المزيد من الخبرة."),
    ItemCard(english: "\"Wow, that's impressive. I hope you get it. Fingers crossed.\"", arabic: "\"واو، هذا مبهر. أتمنى أن تحصل عليها. أدعو لك.\""),
    ItemCard(english: "We can say another word for \"impressive\" like (awesome, admirable, spectacular or excellent).", arabic: "يمكننا قول كلمة أخرى بدلاً من \"impressive\" مثل (awesome، admirable، spectacular أو excellent)."),
    ItemCard(english: "\"Fingers crossed\" This is a hand gesture that we commonly use to wish someone good luck, it's like saying \"I wish you good luck\".", arabic: "\"Fingers crossed\" هذه إشارة يد نستخدمها بشكل شائع لنتمنى لشخص حظاً سعيداً، إنها مثل قول \"أتمنى لك حظاً سعيداً\"."),
    ItemCard(english: "\"We're doing mock interviews.\"", arabic: "\"نحن نتدرب بطريقة مماثلة تماماً للمقابلات الفعلية.\""),
    ItemCard(english: "The word \"mock\" can be used to mean \"laugh at someone or something\" or \"to create something similar to the original object. To make a good copy of it (a replica)\".", arabic: "كلمة \"mock\" يمكن استخدامها بمعنى \"السخرية من شخص أو شيء\" أو \"إنشاء شيء مشابه للشيء الأصلي. لعمل نسخة جيدة منه (نسخة طبق الأصل)\"."),
    ItemCard(english: "Example: It's not okay to mock and disrespect others. Mock = laugh at or tease", arabic: "مثال: لا بأس في السخرية وعدم احترام الآخرين. Mock = يسخر أو يضايق"),
    ItemCard(english: "We always give students mock exams. Mock = replica - a similar copy", arabic: "نحن دائماً نعطي الطلاب امتحانات تجريبية. Mock = نسخة طبق الأصل - نسخة مشابهة"),
    ItemCard(english: "\"That's strange because you're the only one I know who doesn't use fillers in his speech.\"", arabic: "\"هذا غريب لأنك الوحيد الذي أعرفه ولا يستخدم كلمات الحشو في كلامه.\""),
    ItemCard(english: "The word fillers, as the name suggests is something we put in a place to fill it.", arabic: "كلمة fillers، كما يوحي الاسم، هي شيء نضعه في مكان لملئه."),
    ItemCard(english: "When you talk, sometimes we need to think of the next word or we need to choose words carefully. We will end up having a gap in our speech. To fill this gap we use what we call \"fillers\".", arabic: "عندما تتحدث، أحياناً نحتاج للتفكير في الكلمة التالية أو نحتاج لاختيار الكلمات بعناية. سننتهي بوجود فراغ في كلامنا. لملء هذا الفراغ نستخدم ما نسميه \"fillers\"."),
    ItemCard(english: "Fillers words like (you know - uh - mmm - like) we use them to avoid stopping when we talk.", arabic: "كلمات الحشو مثل (you know - uh - mmm - like) نستخدمها لتجنب التوقف عندما نتحدث."),
    ItemCard(english: "Nowadays teenagers overuse fillers in their speech. It's disgusting.", arabic: "في الوقت الحاضر، يفرط المراهقون في استخدام كلمات الحشو في كلامهم. إنه مقزز."),
    ItemCard(english: "I was like you know happy but he was like you know ummm not so much and then we you know told him like come on.", arabic: "كنت مثل تعرف سعيد لكنه كان مثل تعرف ممم ليس كثيراً وبعدها نحن تعرف قلنا له مثل يلا."),
    ItemCard(english: "It's just hurtful to hear. So, it's okay to use fillers every now and then but don't over do it.", arabic: "إنه مؤلم للسمع. لذا، لا بأس في استخدام كلمات الحشو من وقت لآخر ولكن لا تبالغ فيها."),
    ItemCard(english: "\"Let me just stop you there. I was just being sarcastic. Your sister is right, you overuse fillers.\"", arabic: "\"دعني أوقفك عند هذا الحد. كنت فقط أسخر. أختك على حق، أنت تفرط في استخدام كلمات الحشو.\""),
    ItemCard(english: "His friend was just using sarcasm. He was being sarcastic. Sarcasm is when you say the opposite of what you want to say in order to make fun of someone.", arabic: "صديقه كان يستخدم السخرية فقط. كان يسخر. السخرية هي عندما تقول عكس ما تريد قوله بهدف السخرية من شخص ما."),
    ItemCard(english: "Example: You look very tired in the morning and you keep yawning. I look at you and say; wow, I love your energy in the morning.", arabic: "مثال: تبدو متعباً جداً في الصباح وتستمر في التثاؤب. أنظر إليك وأقول: واو، أحب طاقتك في الصباح."),
    ItemCard(english: "The question is: do I mean it? Do I love your energy? No, it is the opposite of what I want to say. You have no energy. So this is sarcasm and I was being sarcastic.", arabic: "السؤال هو: هل أعنيها؟ هل أحب طاقتك؟ لا، إنه عكس ما أريد قوله. ليس لديك طاقة. لذا هذه سخرية وكنت أسخر."),
    ItemCard(english: "Man, Am I excited? I've got my first job interview.", arabic: "يا رجل، كم أنا متحمس! لقد حصلت على أول مقابلة عمل لي."),
    ItemCard(english: "Interview for what?", arabic: "مقابلة عمل من أجل ماذا؟"),
    ItemCard(english: "You know, it's an internship for a big company.", arabic: "أتعلم، إنها فترة تدريب لدى شركة كبيرة."),
    ItemCard(english: "Wow, that's impressive. I hope you get it. Fingers crossed.", arabic: "هذا رائع، أتمنى حصولك عليها. دعواتي لك من أجل ذلك."),
    ItemCard(english: "Well, thanks. I'm preparing for the interview by - you know - practicing with my sister.", arabic: "شكراً، أنا أحضر لمقابلة العمل عن طريق التدرب مع أختي."),
    ItemCard(english: "What exactly are you doing? How are you practicing?", arabic: "ما الذي تفعله تحديداً؟ كيف تتدرب؟"),
    ItemCard(english: "We're doing mock interviews.", arabic: "نحن نتدرب بطريقة مماثلة تماماً للمقابلات الفعلية."),
    ItemCard(english: "Is it helpful?", arabic: "هل هذه الطريقة مفيدة؟"),
    ItemCard(english: "It sure is. She recorded our first interview, and pointed out things that umm - you know - I should avoid.", arabic: "بالتأكيد. قامت بتسجيل أولى مقابلتنا، وأشارت إلى ممم أشياء علي تجنبها."),
    ItemCard(english: "What are some of the things she saw?", arabic: "أخبرني ما هي بعض ملاحظاتها."),
    ItemCard(english: "She said that I said, \"You know\" too much, and that I looked nervous.", arabic: "لقد قالت لي إني أتكلم أكثر مما ينبغي، وأن التوتر ظاهر علي."),
    ItemCard(english: "Oh really, that's strange because you're the only one I know who doesn't use fillers in his speech.", arabic: "حقاً، هذا يبدو غريباً لأنك أنت الوحيد في من أعرفهم الذي يتحدث دون التوقف أثناء كلامه."),
    ItemCard(english: "I know, right? I was like no, I don't do that, but she was kind of like, yeah you do.", arabic: "أعرف، أليس كذلك؟ كنت مثل لا، أنا لا أفعل ذلك، لكنها كانت نوعاً ما مثل، أجل أنت تفعل."),
    ItemCard(english: "Dude, dude. Let me just stop you there. I was just being sarcastic. Your sister is right, you overuse fillers.", arabic: "يا صاحبي، يا صاحبي. دعني أوقفك عند هذا الحد. كنت فقط أسخر. أختك على حق، أنت تفرط في استخدام كلمات الحشو."),
    ItemCard(english: "Hmmm. Well alright then. Time to put an end to that.", arabic: "ممم. حسناً إذن. وقت وضع حد لذلك."),
    ItemCard(english: "Cool! That should help. Good luck my friend.", arabic: "رائع! هذا يجب أن يساعد. حظاً سعيداً يا صديقي."),
    ItemCard(english: "Thanks, man. Appreciate it.", arabic: "شكراً يا رجل. أقدرها."),

    // ===================== Ep16 =====================
    ItemCard(english: "\"I like working with people. I'm a great people person.\"", arabic: "\"أحب العمل مع الناس. أنا شخص اجتماعي.\""),
    ItemCard(english: "A people person is somebody who is very good at interacting with people. They enjoy being around people.", arabic: "الشخص الاجتماعي هو شخص بارع جداً في التفاعل مع الناس. يستمتع بوجوده بين الناس."),
    ItemCard(english: "Some of us are like this, it comes naturally to some of us to know what to say and how to say it. But for some, interaction with people needs a little extra effort.", arabic: "البعض منا هكذا، يأتي بشكل طبيعي للبعض معرفة ما يقولون وكيف يقولونه. لكن للبعض الآخر، يحتاج التفاعل مع الناس إلى جهد إضافي."),
    ItemCard(english: "To be a good team player and blend in, we all need to learn how to make others comfortable talking to us.", arabic: "لكي تكون لاعب فريق جيد وتندمج، نحتاج جميعاً أن نتعلم كيف نجعل الآخرين مرتاحين في التحدث معنا."),
    ItemCard(english: "If you make people comfortable coming to you. We call you approachable.", arabic: "إذا جعلت الناس مرتاحين في القدوم إليك، نسميك approachable (ودود / سهل التعامل)."),
    ItemCard(english: "If you're approachable, you're welcoming, you're friendly and easy to talk to. It's a very good skill.", arabic: "إذا كنت approachable، فأنت مرحب، ودود، وسهل التحدث معك. إنها مهارة جيدة جداً."),
    ItemCard(english: "\"I'm very responsible and I always aspire to meet the expectations that my managers have of me.\"", arabic: "\"أنا مسؤول جداً وأطمح دائماً لتلبية توقعات مدرائي مني.\""),
    ItemCard(english: "The word aspire is a little similar to the word hope or desire.", arabic: "كلمة aspire تشبه قليلاً كلمة hope أو desire."),
    ItemCard(english: "I aspire to do something. = I have a desire to do it or I hope to achieve it.", arabic: "أطمح لفعل شيء ما. = لدي رغبة في فعله أو آمل في تحقيقه."),
    ItemCard(english: "\"Haha you bet but, don't worry. I've seen worse.\"", arabic: "\"هاها بالتأكيد، لكن لا تقلق. لقد رأيت أسوأ من ذلك.\""),
    ItemCard(english: "You bet is slang and means \"yes\", \"you're right\", \"Of course,\" and \"totally\".", arabic: "You bet هي عامية وتعني \"نعم\"، \"أنت على حق\"، \"بالطبع\"، و \"تماماً\"."),
    ItemCard(english: "Example: Person A invites you to dinner. After dinner he asks you if you enjoyed the meal. You can say \"You bet\". It means. \"Yes, I did\".", arabic: "مثال: شخص أ يدعوك للعشاء. بعد العشاء يسألك إذا استمتعت بالوجبة. يمكنك قول \"You bet\". تعني \"نعم، استمتعت\"."),
    ItemCard(english: "\"Sorry. I just like to be always prepared and hey, doesn't this itself show my devotion?\"", arabic: "\"آسف. أنا فقط أحب أن أكون مستعداً دائماً، ويا، ألا يظهر هذا بحد ذاته إخلاصي؟\""),
    ItemCard(english: "The word devotion here means \"loyalty towards something\".", arabic: "كلمة devotion هنا تعني \"الولاء لشيء ما\"."),
    ItemCard(english: "If you love something so much and you're very loyal to it. We say \"you're devoted\".", arabic: "إذا أحببت شيئاً كثيراً وكنت وفياً له جداً، نقول \"أنت مخلص / متفانٍ\"."),
    ItemCard(english: "\"Not to toot my own horn.\" This is a phrase used especially in America and Canada.", arabic: "\"ليس غروراً.\" هذه عبارة تُستخدم خاصة في أمريكا وكندا."),
    ItemCard(english: "It means, to talk about yourself and say very good things. It's like the word \"brag\".", arabic: "تعني أن تتحدث عن نفسك وتقول أشياء جيدة جداً. إنها مثل كلمة \"brag\" (يتفاخر)."),
    ItemCard(english: "\"Wow, ok. Off the top of my head, I think my main weakness is that I don't tolerate sloppy work.\"", arabic: "\"واو، حسناً. من رأس مباشرة، أعتقد أن نقطة ضعفي الأساسية هي أنني لا أتحمل العمل المهمل.\""),
    ItemCard(english: "\"Off the top of my head\" means. I will just say what comes to my mind without thinking first. I will not give any careful thoughts.", arabic: "\"من رأس مباشرة\" تعني أنني سأقول فقط ما يخطر ببالي دون تفكير أولاً. لن أعطي أي أفكار مدروسة بعناية."),
    ItemCard(english: "The word \"tolerate\" means, to allow. The word \"sloppy\" means, careless or disorganized.", arabic: "كلمة \"tolerate\" تعني يسمح. كلمة \"sloppy\" تعني مهمل أو غير منظم."),
    ItemCard(english: "\"... you are a perfectionist or any of that bullsh, please just save it.\" Bullsh is a short way of saying \"Bullshit\".", arabic: "\"... أنت مثالي أو أي من هذا الهراء، من فضلك احتفظ به.\" Bullsh هي طريقة مختصرة لقول \"Bullshit\" (هراء)."),
    ItemCard(english: "Good morning. I'm Robert Stevens.", arabic: "صباح الخير. أنا روبرت ستيفنز."),
    ItemCard(english: "Good morning, Mr. Stevens. My name is Mark Jones.", arabic: "صباح الخير سيد ستيفنز. اسمي مارك جونز."),
    ItemCard(english: "Please have a seat and let's get started.", arabic: "تفضل بالجلوس ودعنا نبدأ."),
    ItemCard(english: "Thank you, Mr. Stevens.", arabic: "شكراً لك سيد ستيفنز."),
    ItemCard(english: "Please call me Robert, and I'll call you Mark. We are informal here.", arabic: "رجاءً نادني روبرت، وأنا سوف أناديك مارك. نحن ننادي بعضنا بشكل غير رسمي."),
    ItemCard(english: "That's good to know, Robert. Thanks.", arabic: "من الجيد معرفة هذا يا روبرت. شكراً لك."),
    ItemCard(english: "Sure, was it easy to find the office?", arabic: "على الرحب، كان من السهل عليك الوصول للمكتب؟"),
    ItemCard(english: "Yeah, it was pretty easy. Plus, I always use GPS.", arabic: "نعم، كان سهلاً، بالإضافة إلى أني دائماً أستخدم GPS."),
    ItemCard(english: "Alright, why don't we start by you telling me a little about yourself?", arabic: "حسناً، لماذا لا نبدأ بأن تخبرني قليلاً عن نفسك؟"),
    ItemCard(english: "Sure. My name is Mark. I graduated from Cairo University in 2016. I'm doing my master's degree in business administration. I like working with people. I'm a great people person. I'm very responsible and I always aspire to meet the expectations that my managers have of me.", arabic: "بالتأكيد. اسمي مارك. تخرجت من جامعة القاهرة عام 2016. أدرس الآن في مرحلة الماجستير وموضوع دراستي هو إدارة الأعمال. أحب العمل مع الناس. أنا شخص اجتماعي. أنا مسؤول وأطمح دوماً أن أكون على مستوى توقعات مديريني."),
    ItemCard(english: "I can tell that your practiced saying that.", arabic: "أنا متأكد من أنك قد تدربت على قول هذا."),
    ItemCard(english: "Was it that obvious?", arabic: "أكان الأمر بهذا الوضوح؟"),
    ItemCard(english: "Haha you bet but, don't worry. I've seen worse.", arabic: "هاهاها، بالتأكيد، لا تقلق لقد رأيت ما هو أسوأ."),
    ItemCard(english: "Sorry. I just like to be always prepared and hey, doesn't this itself show my devotion?", arabic: "آسف. أود فقط أن أكون مستعداً دائماً، ألا يظهر هذا ذاته إخلاصي؟"),
    ItemCard(english: "You're right, it kinda does.", arabic: "أنت على حق، بالفعل يشير إلى حد ما."),
    ItemCard(english: "Not to toot my own horn, but I really think that I'm an excellent candidate for the job.", arabic: "ليس غروراً، بالنسبة لي أعتقد أني المرشح المثالي لهذه الوظيفة."),
    ItemCard(english: "I see you have two years of experience. Can you tell me a little about that?", arabic: "أرى أن لديك سنتين من الخبرة. أيمكنك أن تحدثني عن ذلك؟"),
    ItemCard(english: "Oh, yes. I worked in the mailroom at ABC Corporation last year.", arabic: "نعم، عملت بغرفة البريد لدى مؤسسة ABC في العام الماضي."),
    ItemCard(english: "Go on, please.", arabic: "استمر رجاءً."),
    ItemCard(english: "It was a temporary job, but I gained a lot of experience.", arabic: "كان عملاً مؤقتاً، ولكني حصلت على العديد من الخبرات."),
    ItemCard(english: "Excellent! We are always looking for someone with experience.", arabic: "ممتاز! نحن دائماً نبحث عن ذوي الخبرة."),
    ItemCard(english: "I think this experience will help me blend into a job working here.", arabic: "أعتقد أن هذه الخبرة ستساعدني على الاندماج في عملي هنا."),
    ItemCard(english: "What are your weaknesses, Mark? Before you say anything. Please bear in mind that I heard all the ideal answers, so if you're going to tell me that your weaknesses are that you're very patient or that you take up too many tasks or you are a perfectionist or any of that bullsh, please just save it. Ok?", arabic: "ما هي نقاط ضعفك يا مارك؟ قبل أن تقول أي شيء. من فضلك ضع في اعتبارك أني سمعت كل الأجابات النموذجية، لذا إذا كنت ستخبرني أن نقاط ضعفك هي أنك صبور للغاية أو أنك تتولى الكثير من المهام أو أنك كامل أو أي من هذه الهراء، رجاءً احتفظ به. حسناً؟"),
    ItemCard(english: "Wow, ok. Off the top of my head, I think my main weakness is that I don't tolerate sloppy work. Sometimes I come across as a tough person but that's how you can lead.", arabic: "حسناً، أول ما خطر ببالي دون تفكير، أعتقد أن نقاط ضعفي الأساسية هي أني لا أتساهل مع التخاذل في العمل. أحياناً أكون شخص شديد ولكن هذا ما يتطلبه الأمر حتى تستطيع القيادة."),
    ItemCard(english: "Alright, Mark. I like this answer.", arabic: "حسناً يا مارك، أعجبتني هذه الإجابة."),
    ItemCard(english: "Thank you, Sir.", arabic: "شكراً لك سيدي."),
    ItemCard(english: "Do you have any questions for me?", arabic: "هل لديك أي أسئلة لي؟"),
    ItemCard(english: "Well, I've already done my homework and learned everything I need to learn from the internet, but I would like to know when to expect a call from you.", arabic: "حسناً، لقد قمت بالفعل بأداء واجبي وتعلمت كل شيء أحتاج أن أتعلمه من الإنترنت، ولكن أود أن أعرف متى أتوقع مكالمة منكم."),
    ItemCard(english: "You'll be contacted by an HR representative within two weeks.", arabic: "سوف تتلقى اتصالاً من ممثل الموارد البشرية في خلال أسبوعين."),
    ItemCard(english: "Great, thanks again for having me.", arabic: "رائع، شكراً مجدداً على مقابلتي."),
    ItemCard(english: "Thanks for coming. Have a good day.", arabic: "شكراً لقدومك. أتمنى لك يوماً جيداً."),
    ItemCard(english: "You too, Sir.", arabic: "وأنت أيضاً سيدي."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Lv2 Summary 3 - الجمل (Ep13 → Ep16)",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


